{"code":"BICHM 322","title":"Physical Chemistry II","department":"Biochemistry","credits":1,"description":"A study of the fundamental concepts and principles of thermodynamics and kinetics. Topics include statistical and classical thermodynamics, prediction of the direction and extent of chemical reactions, equilibrium, chemical kinetics, catalysis, and reaction rate theory. The department recommends that students take CHEM-321 prior to CHEM-322. Three hours of lecture.","cross_listed":["CHEM 322"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/bichm-biochemistrymolecular-biology/300/bichm-322","sections":[{"days":"MWF","room":null,"types":["Quantitative & Symbolic R"],"status":"open","section":"01","building":null,"capacity":40,"comments":"The department recommends that students take 321 prior to 322.","end_time":"10:50:00","meetings":[{"days":"MWF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"10:50","start_date":"2027-01-20","start_time":"10:00"}],"start_time":"10:00:00","instructors":["Wesley W. Kramer"]}]},
{"code":"BICHM 551","title":"Senior Thesis II","department":"Biochemistry","credits":1,"description":"A research project carried out in association with a faculty member. Includes written and oral presentations. Candidates for honors should elect both 550 and 551. Prerequisites: BICHM 550. One course credit.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/bichm-biochemistrymolecular-biology/500/bichm-551","sections":[{"days":"F","room":null,"types":["Senior Project"],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":"16:00:00","meetings":[{"days":"F","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"15:00"}],"start_time":"15:00:00","instructors":["Max M. Majireck"]},{"days":"M","room":null,"types":["Senior Project"],"status":"open","section":"02","building":null,"capacity":40,"comments":null,"end_time":"15:00:00","meetings":[{"days":"M","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"15:00","start_date":"2027-01-20","start_time":"14:30"}],"start_time":"14:30:00","instructors":["Rhea R. Datta"]},{"days":null,"room":null,"types":["Senior Project"],"status":"open","section":"03","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Wei-Jen Chang"]},{"days":"F","room":null,"types":["Senior Project"],"status":"open","section":"04","building":null,"capacity":40,"comments":null,"end_time":"16:00:00","meetings":[{"days":"F","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"15:00"}],"start_time":"15:00:00","instructors":["Michael A. Welsh"]},{"days":"F","room":null,"types":["Senior Project"],"status":"open","section":"06","building":null,"capacity":40,"comments":null,"end_time":"12:50:00","meetings":[{"days":"F","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"12:50","start_date":"2027-01-20","start_time":"12:00"}],"start_time":"12:00:00","instructors":["Natalie J. Nannas"]},{"days":"F","room":null,"types":["Senior Project"],"status":"open","section":"07","building":null,"capacity":40,"comments":null,"end_time":"16:00:00","meetings":[{"days":"F","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"15:00"}],"start_time":"15:00:00","instructors":["Michael L. McCormick"]},{"days":null,"room":null,"types":["Senior Project"],"status":"open","section":"09","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Ariel F. Kahrl"]},{"days":null,"room":null,"types":["Senior Project"],"status":"open","section":"10","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Elena Tonc"]},{"days":null,"room":null,"types":["Senior Project"],"status":"open","section":"11","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Andrea K. Townsend"]},{"days":"F","room":null,"types":["Senior Project"],"status":"open","section":"12","building":null,"capacity":40,"comments":null,"end_time":"16:00:00","meetings":[{"days":"F","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"15:00"}],"start_time":"15:00:00","instructors":["Ryan J. Martinie"]}]},
{"code":"BIO 100B","title":"Exb: Frankenstein Fish","department":"Biology","credits":1,"description":"A thematic course exploring five fundamental features of all biological systems, including structure and function, information flow, energy and matter, interactions, and evolution. As humans continue to exploit the ocean's resources by overfishing, aquaculture and mariculture have become more and more important to meet human demands for fish proteins. This course will examine overfishing, genetically modified/engineered foods, and animal cloning and engineering to introduce fundamental concepts of ecology, ecosystems and conservation biology, genetics and molecular biology, and ethical issues. Students must concurrently enroll in a Bio100L lab section. Not open to students who have taken any other Explorations in Biology course.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/bio-biology/100/bio-100b","sections":[{"days":"MWF","room":null,"types":["Quantitative & Symbolic R","Soc, Struct & Inst Hier"],"status":"open","section":"01","building":null,"capacity":30,"comments":null,"end_time":"11:50:00","meetings":[{"days":"MWF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"11:50","start_date":"2027-01-20","start_time":"11:00"}],"start_time":"11:00:00","instructors":["Wei-Jen Chang"]}]},
