{"code":"BIO 221","title":"Microbiology","department":"Biology","credits":1,"description":"Introduction to microorganisms, including bacteria, archaea, single-cell eukaryotes (yeast, algae, protozoa) and viruses, with an emphasis on prokaryotic metabolism and ecology. Basic laboratory techniques, including isolation, cultivation and characterization of microbes. Three hours of class and three hours of laboratory. Prerequisites, 100, or 101, or 102, or 115 and Chemistry 120 or 125, or consent of instructor.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/bio-biology/200/bio-221","sections":[{"days":"TR","room":null,"types":["Quantitative & Symbolic R","Soc, Struct & Inst Hier"],"status":"open","section":"01","building":null,"capacity":20,"comments":null,"end_time":"10:15:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"10:15","start_date":"2027-01-20","start_time":"09:00"}],"start_time":"09:00:00","instructors":["Michael L. McCormick"]}]},
