{"code":"BIO 228","title":"Invertebrate Biology","department":"Biology","credits":1,"description":"Survey of animal diversity, including marine and freshwater fauna, parasites, insects and the origin of vertebrates. Emphasis on morphology, physiology, ecology and evolution. Three hours of class, three hours of laboratory. Prerequisites, 100, or 101, or 102, or 115, or consent of instructor.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/bio-biology/200/bio-228","sections":[{"days":"MWF","room":null,"types":[],"status":"waitlisted","section":"01","building":null,"capacity":20,"comments":null,"end_time":"10:50:00","meetings":[{"days":"MWF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"10:50","start_date":"2027-01-20","start_time":"10:00"}],"start_time":"10:00:00","instructors":["Patrick D. Reynolds"]}]},
{"code":"BIO 228L","title":"Invertebrate Biology Lab","department":"Biology","credits":0,"description":"This is the lab that is required for the BIO 228 lecture. Both a lab section as well as a lecture section must be taken in the same semester.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/bio-biology/200/bio-228","sections":[{"days":"T","room":"2026","types":[],"status":"waitlisted","section":"01","building":"Taylor Science Center","capacity":20,"comments":null,"end_time":"16:00:00","meetings":[{"days":"T","room":"2026","type":"LAB","building":"Taylor Science Center","end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Patrick D. Reynolds"]}]},
{"code":"BIO 270","title":"Biological Chemistry","department":"Biology","credits":1,"description":"A survey of the chemical and physical nature of biological macromolecules, including nucleic acids, proteins, lipids and carbohydrates; biochemistry of enzyme catalysis; bioenergetics and regulatory mechanisms. Principles and techniques of experimental biochemistry, focusing on isolation methods and techniques for analyzing structure and function. This course satisfies the second semester of a one-year General Chemistry requirement for post-graduate Health Professions programs, however, this course might not also satisfy a Health Profession program's requirement for a course in Biochemistry. Three hours of class and three hours of laboratory.","cross_listed":["BICHM 270","CHEM 270"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/bio-biology/200/bio-270","sections":[{"days":"MWF","room":null,"types":["Qlit Course","Quantitative & Symbolic R"],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":"09:50:00","meetings":[{"days":"MWF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"09:50","start_date":"2027-01-20","start_time":"09:00"}],"start_time":"09:00:00","instructors":["Ryan J. Martinie"]},{"days":"MWF","room":null,"types":["Qlit Course","Quantitative & Symbolic R"],"status":"waitlisted","section":"02","building":null,"capacity":40,"comments":null,"end_time":"10:50:00","meetings":[{"days":"MWF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"10:50","start_date":"2027-01-20","start_time":"10:00"}],"start_time":"10:00:00","instructors":["Michael A. Welsh"]}]},
