{"code":"CHEM 120","title":"Principles of Chemistry","department":"Chemistry","credits":1,"description":"Exploration of the central principles and theories of chemistry including stoichiometry, thermodynamics, equilibrium, reaction kinetics, and molecular structure and bonding. For students intending to pursue post-graduate work in the Health Professions, this course satisfies the first semester of a one-year General Chemistry requirement. Three hours of lecture and three hours of laboratory.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/chem-chemistry/100/chem-120","sections":[{"days":"TR","room":null,"types":["Environmental Studies","Qlit Course","Quantitative & Symbolic R"],"status":"open","section":"01","building":null,"capacity":40,"comments":"Open to Srs., Jrs., Soph., & 1st Years","end_time":"11:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"11:45","start_date":"2027-01-20","start_time":"10:30"}],"start_time":"10:30:00","instructors":["Carolyn P. Hutchinson"]}]},
