{"code":"CHEM 190","title":"Organic Chemistry I","department":"Chemistry","credits":1,"description":"Structure and bonding of organic compounds and their acid-base properties, stereochemistry, introduction to reactions and reaction mechanisms of carbon compounds and the relationship of reactivity and structure. Three hours of class and three hours of laboratory.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/chem-chemistry/100/chem-190","sections":[{"days":"MWF","room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":"Open to Srs., Jrs., Soph., & 1st Yrs. STUDENTS SIGNING UP FOR CHEM 190 MUST ALSO SIGN UP FOR A CHEM 190L SECT","end_time":"09:50:00","meetings":[{"days":"MWF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"09:50","start_date":"2027-01-20","start_time":"09:00"}],"start_time":"09:00:00","instructors":["Ronald T. Jerozal"]},{"days":"MWF","room":null,"types":[],"status":"waitlisted","section":"02","building":null,"capacity":40,"comments":"Open to Srs., Jrs., Soph., & 1st Yrs. STUDENTS SIGNING UP FOR CHEM 190 MUST ALSO SIGN UP FOR A CHEM 190L SECTION.","end_time":"10:50:00","meetings":[{"days":"MWF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"10:50","start_date":"2027-01-20","start_time":"10:00"}],"start_time":"10:00:00","instructors":["Ian J. Rosenstein"]},{"days":"MWF","room":null,"types":[],"status":"waitlisted","section":"03","building":null,"capacity":40,"comments":"Open to Srs., Jrs., Soph., & 1st Yrs. STUDENTS SIGNING UP FOR CHEM 190 MUST ALSO SIGN UP FOR A CHEM 190L SECTION.","end_time":"11:50:00","meetings":[{"days":"MWF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"11:50","start_date":"2027-01-20","start_time":"11:00"}],"start_time":"11:00:00","instructors":["Max M. Majireck"]}]},
