{"code":"CHEM 265","title":"Inorganic Chemistry","department":"Chemistry","credits":1,"description":"Topics in inorganic chemistry, including periodicity and descriptive chemistry of the elements, electrochemistry, transition metal coordination chemistry, and the structure and properties of solid state materials. Laboratories emphasize synthesis and characterization of inorganic coordination compounds, electrochemistry, and inorganic materials. This course satisfies the second semester of a one-year General Chemistry requirement for post-graduate Health Professions programs. Three hours of lecture and three hours of laboratory.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/chem-chemistry/200/chem-265","sections":[{"days":"TR","room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":"Must also register for a CHEM 265 lab. Open to Srs., Jrs., Soph., & 1st Yrs.","end_time":"11:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"11:45","start_date":"2027-01-20","start_time":"10:30"}],"start_time":"10:30:00","instructors":["Karen S. Brewer"]}]},
