{"code":"CHEM 270","title":"Biological Chemistry","department":"Chemistry","credits":1,"description":"A survey of the chemical and physical nature of biological macromolecules, including nucleic acids, proteins, lipids and carbohydrates; biochemistry of enzyme catalysis; bioenergetics and regulatory mechanisms. Principles and techniques of experimental biochemistry, focusing on isolation methods and techniques for analyzing structure and function. This course satisfies the second semester of a one-year General Chemistry requirement for post-graduate Health Professions programs, however, this course might not also satisfy a Health Profession program's requirement for a course in Biochemistry. Three hours of class and three hours of laboratory.","cross_listed":["BICHM 270","BIO 270"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/chem-chemistry/200/chem-270","sections":[{"days":"MWF","room":null,"types":["Qlit Course","Quantitative & Symbolic R"],"status":"open","section":"01","building":null,"capacity":40,"comments":"Students must also register for a CHEM 270 lab.","end_time":"09:50:00","meetings":[{"days":"MWF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"09:50","start_date":"2027-01-20","start_time":"09:00"}],"start_time":"09:00:00","instructors":["Ryan J. Martinie"]},{"days":"MWF","room":null,"types":["Qlit Course","Quantitative & Symbolic R"],"status":"waitlisted","section":"02","building":null,"capacity":40,"comments":"Students must also register for a CHEM 270 lab.","end_time":"10:50:00","meetings":[{"days":"MWF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"10:50","start_date":"2027-01-20","start_time":"10:00"}],"start_time":"10:00:00","instructors":["Michael A. Welsh"]}]},
