{"code":"CHEM 298","title":"Chemistry Research","department":"Chemistry","credits":0.25,"description":"Independent work in the research laboratory under supervision of a faculty member. Prerequisites, instructor's signature. May be repeated for credit, but not counted toward concentration or minor requirements. Students may count up to one credit of chemistry research toward graduation. One-quarter, one-half or one credit per semester. No senior concentrators.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/chem-chemistry/200/chem-298","sections":[{"days":null,"room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":"Instructor's Signature Req.","end_time":null,"meetings":[],"start_time":null,"instructors":["Ian J. Rosenstein"]}]},
{"code":"CHEM 322","title":"Physical Chemistry II","department":"Chemistry","credits":1,"description":"A study of the fundamental concepts and principles of thermodynamics and kinetics. Topics include statistical and classical thermodynamics, prediction of the direction and extent of chemical reactions, equilibrium, chemical kinetics, catalysis, and reaction rate theory. The department recommends that students take CHEM-321 prior to CHEM-322. Three hours of lecture.","cross_listed":["BICHM 322"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/chem-chemistry/300/chem-322","sections":[{"days":"MWF","room":null,"types":["Quantitative & Symbolic R"],"status":"open","section":"01","building":null,"capacity":40,"comments":"The department recommends that students take 321 prior to 322.","end_time":"10:50:00","meetings":[{"days":"MWF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"10:50","start_date":"2027-01-20","start_time":"10:00"}],"start_time":"10:00:00","instructors":["Wesley W. Kramer"]}]},
{"code":"CHEM 325","title":"Physical Method Chem Analysis","department":"Chemistry","credits":1,"description":"An integrated lecture-laboratory course in which students learn to design, build, and use instrumentation to study the physicochemical properties of atoms and molecules. Topics include the theory and practice of optical spectroscopy, thermochemical measurements of gases and condensed phases, and the measurement of reaction kinetics. Evaluations stress mastery of laboratory technique and communication of results with an emphasis on oral communication. Speaking-Intensive. One hour of lecture, three hours of laboratory.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/chem-chemistry/300/chem-325","sections":[{"days":"M","room":null,"types":["Quantitative & Symbolic R","Speaking Intensive Course"],"status":"open","section":"01","building":null,"capacity":12,"comments":null,"end_time":"12:50:00","meetings":[{"days":"M","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"12:50","start_date":"2027-01-20","start_time":"12:00"},{"days":"M","room":null,"type":"LAB","building":null,"end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"12:00:00","instructors":["Carolyn P. Hutchinson"]}]},
{"code":"CHEM 345","title":"Organometallic Catalysis","department":"Chemistry","credits":0.5,"description":"Readings in the primary chemical literature pairing historical and modern papers to examine organometallic bonding, catalysis, and the experimental evidence used to validate catalytic cycles. One-half credit seminar.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/chem-chemistry/300/chem-345","sections":[{"days":"TR","room":null,"types":[],"status":"waitlisted","section":"01","building":null,"capacity":12,"comments":"Restricted to CHEM majors. 0.5 credit course; runs 3/29/27-5/17/27","end_time":"10:15:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"10:15","start_date":"2027-03-29","start_time":"09:00"}],"start_time":"09:00:00","instructors":["Karen S. Brewer"]}]},
{"code":"CHEM 347","title":"Environ Chem and Lit","department":"Chemistry","credits":1,"description":"An exploration of how environmental chemistry shapes environmental literature. Course material will include primary chemical sources as well as essays, novels, short stories, film, and other environmental literature. This course will look at both natural environmental chemistry as well as the chemistry of anthropogenic changes and compounds, such as pesticides. Students will interrogate and discuss these connections then use them to discover their own intersections with chemistry and literature.","cross_listed":["ENVST 347"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/chem-chemistry/300/chem-347","sections":[{"days":"TR","room":null,"types":["Speaking Intensive Course"],"status":"open","section":"01","building":null,"capacity":20,"comments":null,"end_time":"14:15:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Carolyn P. Hutchinson"]}]},
{"code":"CHEM 348","title":"Sci, Technology & Society","department":"Chemistry","credits":0.5,"description":"An examination of the assumptions, paradigms, and hierarchies embedded in science and technology. This course will examine evidence pointing to the structure of hierarchies built into and from science and how those structures may result in inequalities for various groups participating in and affected by science and technology. Topics will vary but might include: the objectivity/subjectivity of science; how biases and social structures intersect with equity, diversity, and inclusion in science; and gender and race disparities in STEM fields.","cross_listed":["PHYS 348"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/chem-chemistry/300/chem-348","sections":[{"days":"WF","room":null,"types":["Soc, Struct & Inst Hier"],"status":"open","section":"01","building":null,"capacity":40,"comments":"Restricted to CHEM and PHYS majors. 0.5 credit class; Runs from 1/20/27 to 3/12/27.","end_time":"14:15:00","meetings":[{"days":"WF","room":null,"type":"LEC","building":null,"end_date":"2027-03-12","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Karen S. Brewer"]}]},
{"code":"CHEM 361","title":"Advanced Organic Spectroscopy","department":"Chemistry","credits":0.5,"description":"A study of advanced topics in NMR spectroscopy and mass spectrometry with a focus on practical interpretation of spectra. Topics include NMR theory, chemical shift, spin-spin coupling, dynamic NMR, 2D NMR techniques (COSY, NOESY, HSQC/HMQC, HMBC), methods of ionization in mass spectrometry, and interpretation of mass spectral fragmentation patterns. One-half credit.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/chem-chemistry/300/chem-361","sections":[{"days":"TR","room":null,"types":[],"status":"waitlisted","section":"01","building":null,"capacity":18,"comments":"0.5 credit class; Runs from 1/20/27 to 3/12/27. Instructor's signature required.","end_time":"10:15:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-03-12","end_time":"10:15","start_date":"2027-01-20","start_time":"09:00"}],"start_time":"09:00:00","instructors":["Ian J. Rosenstein"]}]},
{"code":"CHEM 552","title":"Senior Project","department":"Chemistry","credits":1,"description":null,"cross_listed":[],"catalog_url":null,"sections":[{"days":null,"room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Karen S. Brewer","Michael A. Welsh"]}]},
{"code":"CHNSE 120","title":"Second Term Chinese","department":"Chinese","credits":1,"description":"This course is the second semester in introductory level of Chinese. The course will cover the remaining five units (Unit 6-10) of the learning materials, Basic Mandarin Chinese (Speaking & Listening; Reading & Writing). The course will help students further develop skills in Mandarin Chinese to conduct basic communication across ethnic, cultural and ideological boundaries and to develop an understanding of Chinese interpersonal behavioral culture. At the end of the course, students will be expected to perform in speaking, listening, reading and writing Chinese at a level of proficiency appropriate for continuing on to the intermediate level of Chinese courses. They should also demonstrate a level of cultural understanding suitable for correct performance of assigned tasks in Chinese.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/chnse-chinese/100/chnse-120","sections":[{"days":"MW","room":null,"types":[],"status":"open","section":"01","building":null,"capacity":16,"comments":null,"end_time":"11:50:00","meetings":[{"days":"MW","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"11:50","start_date":"2027-01-20","start_time":"11:00"},{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"12:50","start_date":"2027-01-20","start_time":"12:00"}],"start_time":"11:00:00","instructors":["Tiao-Guan Huang"]},{"days":"MW","room":null,"types":[],"status":"open","section":"02","building":null,"capacity":16,"comments":null,"end_time":"12:50:00","meetings":[{"days":"MW","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"12:50","start_date":"2027-01-20","start_time":"12:00"},{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"11:50","start_date":"2027-01-20","start_time":"11:00"}],"start_time":"12:00:00","instructors":["Tiao-Guan Huang"]}]},
{"code":"CHNSE 140","title":"Fourth Term Chinese","department":"Chinese","credits":1,"description":"Continuation of third-term Chinese. Development of spoken and written skills, as well as familiarity with current Chinese culture. Class discussions in Chinese. Four hours of class, with additional lab work and individual sessions for each student.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/chnse-chinese/100/chnse-140","sections":[{"days":"WF","room":null,"types":["Cultural Diversity Course"],"status":"open","section":"01","building":null,"capacity":16,"comments":null,"end_time":"09:50:00","meetings":[{"days":"WF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"09:50","start_date":"2027-01-20","start_time":"09:00"},{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"09:50","start_date":"2027-01-20","start_time":"09:00"}],"start_time":"09:00:00","instructors":["Tiao-Guan Huang"]}]},
{"code":"CHNSE 220","title":"Advanced Chinese II","department":"Chinese","credits":1,"description":"Continuation of Advanced Chinese I, with emphasis on making the transition from textbook to an advanced level of competence for reading periodicals and journals in China. Discussion, written and oral work. Taught in Chinese.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/chnse-chinese/200/chnse-220","sections":[{"days":"TR","room":null,"types":["Cultural Diversity Course","Proseminar"],"status":"open","section":"01","building":null,"capacity":16,"comments":null,"end_time":"14:15:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Zhuoyi Wang"]}]},
{"code":"CHNSE 243","title":"East Asian Women in Film","department":"Chinese","credits":1,"description":"This course examines portrayals of East Asian women in mainland Chinese, Hong Kong, Taiwanese, Japanese, Korean, and Hollywood films, with an emphasis on the post-#MeToo era. Through close analysis of narrative films and documentaries, students learn to investigate how gendered experiences of oppression, resilience, and resistance are represented, challenged, and reimagined in diverse cultural contexts. Combining film studies and gender studies, the course highlights both shared and divergent regional patterns and encourages students to consider how cinema shapes public debates on social change, agency, and justice. All films include English subtitles. Course requirements include film viewings, presentations, active discussion, a creative project, and a final paper.","cross_listed":["CNMS 243"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/chnse-chinese/200/chnse-243","sections":[{"days":"TR","room":null,"types":["Soc, Struct & Inst Hier"],"status":"open","section":"01","building":null,"capacity":40,"comments":"Open to Srs., Jrs., Soph., & 1st Years.","end_time":"15:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"15:45","start_date":"2027-01-20","start_time":"14:30"}],"start_time":"14:30:00","instructors":["Zhuoyi Wang"]}]},
{"code":"CHNSE 446","title":"Taiwan Through Film","department":"Chinese","credits":1,"description":"This course is an advanced-level Chinese language and Chinese-speaking culture course. It explores the complex cinematic depictions of Taiwan's history, politics, and culture across the greater Chinese-speaking world. At the same time, it provides advanced-level Chinese language training. Through this dual focus, students will gain a nuanced perspective on Taiwan's role in shaping cinematic narratives while gaining the language proficiency needed to participate fluently in discussions on both familiar and abstract topics, present structured arguments, and articulate in-depth analyses and sophisticated ideas in Chinese.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/chnse-chinese/400/chnse-446","sections":[{"days":"MW","room":null,"types":["Soc, Struct & Inst Hier","Speaking Intensive Course"],"status":"open","section":"01","building":null,"capacity":20,"comments":null,"end_time":"15:45:00","meetings":[{"days":"MW","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"15:45","start_date":"2027-01-20","start_time":"14:30"}],"start_time":"14:30:00","instructors":["Zhuoyi Wang"]}]},
{"code":"CHNSE 550","title":"Senior Project","department":"Chinese","credits":1,"description":"A research project using sources in Chinese culminating in a paper, designed by the student, in consultation with at least two members of the East Asian Languages and Literatures Department. Students are expected to develop analytical and linguistic skills in the Chinese language through culture study in upper-level coursework and/or study abroad. Limited to senior Chinese concentrators.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/chnse-chinese/500/chnse-550","sections":[{"days":null,"room":null,"types":[],"status":"open","section":"01","building":null,"capacity":6,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Zhuoyi Wang"]}]},
{"code":"CLASC 115","title":"Ancient Greek Hist & Culture","department":"Classics","credits":1,"description":"An introduction to the legacy of ancient Greece through the study of history, literature, philosophy, and art. This course will also consider the influence of neighboring cultures on Ancient Greece, including the Egyptians, the Phoenicians, and the Persians, to name a few.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/clasc-classical-studies/100/clasc-115","sections":[{"days":"TR","room":null,"types":["Soc, Struct & Inst Hier"],"status":"open","section":"01","building":null,"capacity":40,"comments":"Open to 1st Yrs, Soph. & Jrs. Only","end_time":"15:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"15:45","start_date":"2027-01-20","start_time":"14:30"}],"start_time":"14:30:00","instructors":[]}]},
{"code":"CLASC 207","title":"Social Lives Ancient Dead","department":"Classics","credits":1,"description":"What happened to people after they died in the ancient world? Often, their story was only beginning. This course looks at the ways the dead remained part of everyday life. We will read curse tablets that call on restless spirits, laws about stolen bodies, stories about cities fighting over heroic bones, and Christian accounts of remains that heal or protect the living. We will also study tombs and inscriptions to see how people used the dead to make claims about family, memory, status, and belonging. The course ends close to home. For the final project, students will turn to Hamilton's own cemetery and investigate how one grave, monument, or burial story creates a social life for the dead on our campus. The larger question throughout the course is simple: what can the dead still do for the living? (Application, Interpretation)","cross_listed":["RELST 207"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/clasc-classical-studies/200/clasc-207","sections":[{"days":"TR","room":null,"types":[],"status":"waitlisted","section":"01","building":null,"capacity":40,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"11:45","start_date":"2027-01-20","start_time":"10:30"}],"start_time":"10:30:00","instructors":["Sunil Persad"]}]},
{"code":"CLASC 227W","title":"Race, Ethnicity: Greece, Rome","department":"Classics","credits":1,"description":"In this course, we will examine social constructions of race and ethnicity in Ancient Greece and Rome. What evidence survives, both textual and material, and what challenges do we face in interpreting it? How do conceptions of race differ by place and time through the Greco-Roman world? What is the difference between race and ethnicity? How have ancient ideas of race and racial hierarchies influenced later ones, and how have modern ideas influenced our interpretations of the past? This 200-level section is specifically designed to be part of a Justice Lab. Students who are interested in this course, but NOT planning to enroll in the Justice Lab, should consider the 300-level companion course, CLASC-327.","cross_listed":["CLASC 327W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/clasc-classical-studies/200/clasc-227","sections":[{"days":"TR","room":null,"types":["Co-Lab Course","Soc, Struct & Inst Hier","Writing Intensive Courses"],"status":"waitlisted","section":"01","building":null,"capacity":10,"comments":"CLASC 227W is open to Spring 2027 Justice Lab students only. The 300-level is open to non-Justice Lab students with instructor's permission.","end_time":"15:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"15:45","start_date":"2027-01-20","start_time":"14:30"}],"start_time":"14:30:00","instructors":["Anne C. Feltovich","Amy A. Koenig"]}]},
{"code":"CLASC 327W","title":"Race, Ethnicity: Greece, Rome","department":"Classics","credits":1,"description":"In this course, we will examine social constructions of race and ethnicity in Ancient Greece and Rome. What evidence survives, both textual and material, and what challenges do we face in interpreting it? How do conceptions of race differ by place and time through the Greco-Roman world? What is the difference between race and ethnicity? How have ancient ideas of race and racial hierarchy influenced later ones, and how have modern ideas influenced our interpretations of the past? This course requires no knowledge of Ancient Greek or Latin, but students with such knowledge can aid in our discussions of problems introduced by translations.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/clasc-classical-studies/300/clasc-327","sections":[{"days":"TR","room":null,"types":["Soc, Struct & Inst Hier","Writing Intensive Courses"],"status":"open","section":"01","building":null,"capacity":16,"comments":"First Years require instructor permission.","end_time":"15:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"15:45","start_date":"2027-01-20","start_time":"14:30"}],"start_time":"14:30:00","instructors":["Anne C. Feltovich","Amy A. Koenig"]}]},
{"code":"CLASC 550","title":"Senior Program","department":"Classics","credits":1,"description":"Topics to be arranged. Open only to senior concentrators.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/clasc-classical-studies/500/clasc-550","sections":[{"days":"WF","room":null,"types":["Soc, Struct & Inst Hier"],"status":"open","section":"01","building":null,"capacity":12,"comments":"Restricted to Senior Clasc Majors","end_time":"14:15:00","meetings":[{"days":"WF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Amy A. Koenig"]}]},
{"code":"CNMS 103W","title":"Art of Advertising","department":"Cinema and Media Studies","credits":1,"description":"Advertising images are everywhere, beckoning us to look and believe their message. But how do such images actually work, and where do their visual strategies come from? This writing-intensive seminar equips students with the foundational skills of visual and contextual analysis necessary for the study of art and visual media. We will study how artists, designers, photographers, and advertising professionals created influential campaigns in print, on television, and online. Students will learn to analyze how images and text work together, how ads capture our attention, how they borrow from different visual traditions, and how they shape our desires, often through troubling visual conventions.","cross_listed":["ARTH 103W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/cnms-cinema-and-media-studies/100/cnms-103","sections":[{"days":"MW","room":null,"types":["Writing Intensive Courses"],"status":"waitlisted","section":"01","building":null,"capacity":18,"comments":"Open to 1st Yrs and Sophomores only","end_time":"14:15:00","meetings":[{"days":"MW","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Nadya Bair"]}]},
{"code":"CNMS 145","title":"World Films, World Faiths","department":"Cinema and Media Studies","credits":1,"description":"Introduces the practices and beliefs of several major world religions (including Judaism, Christianity, Islam, Hinduism and Buddhism) through the medium of film. Exploring Japanese anime, Indonesia documentaries, video films from Ghana, Bollywood mythologicals, Jesus-films from Latin America, Korean-Buddhist films, contemporary fictional glimpses into Jewish life, and more, shows how religious people live and struggle and find joy, by using the audio-visual medium of film. Evening film screenings.","cross_listed":["RELST 145"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/cnms-cinema-and-media-studies/100/cnms-145","sections":[{"days":"MW","room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":"Open to 1st Yrs, Soph. & Jrs. Only","end_time":"09:45:00","meetings":[{"days":"MW","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"09:45","start_date":"2027-01-20","start_time":"08:30"},{"days":"U","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"22:00","start_date":"2027-01-20","start_time":"19:00"}],"start_time":"08:30:00","instructors":["S.B. Rodriguez-Plate"]}]},
{"code":"CNMS 230","title":"Bollywood Film","department":"Cinema and Media Studies","credits":1,"description":"The course charts a history of Bollywood, India's mainstream Hindi-language film industry. Although dismissed for its use of melodrama and song-dance sequences, Bollywood has long engaged with other global cinemas and critiqued social, cultural, and political trends. Readings and films span romances about gender and nation like Mother India (1957) and Chaudhvin Ka Chand (1960); the 1970s \"angry young man\" oeuvre and its later avatars, crime and terrorist films; diasporic family dramas like Kal Ho Naa Ho (2003); and crossover hits like The Lunch Box (2013) that address the globalized present. (History, Genre)","cross_listed":["LIT 230"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/cnms-cinema-and-media-studies/200/cnms-230","sections":[{"days":"TR","room":null,"types":[],"status":"waitlisted","section":"01","building":null,"capacity":40,"comments":null,"end_time":"10:15:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"10:15","start_date":"2027-01-20","start_time":"09:00"}],"start_time":"09:00:00","instructors":["Pavitra Sundar"]}]},
{"code":"CNMS 232","title":"Resistance History Thru Film","department":"Cinema and Media Studies","credits":1,"description":"Through films and documentaries about places with contentious histories and ongoing political conflicts, this course will examine the solidarities and fractures that resistance against colonial and foreign control brings about in struggling societies. The course will particularly explore the anticolonial struggles of Palestinians, Algerians, Irish, Kurds, Kashmiris, Tamils, and Indigenous Americans, among others, and in doing so engage with themes of sovereignty and self-determination, nationality and belonging, and history and memory. Such inquiries not only have real-world stakes for peoples' survival and political identities, but also shape in profound ways the imaginations and practices of resistance and solidarity across the globe.","cross_listed":["ASNST 232","HIST 232","MEIWS 232"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/cnms-cinema-and-media-studies/200/cnms-232","sections":[{"days":"T","room":null,"types":[],"status":"open","section":"01","building":null,"capacity":20,"comments":"Open to Srs., Jrs., Soph., & 1st Yr","end_time":"16:00:00","meetings":[{"days":"T","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Suvaid Yaseen"]}]},
{"code":"CNMS 238W","title":"Films of the Coen Brothers","department":"Cinema and Media Studies","credits":1,"description":"This course will analyze the way the Coen Brothers' films play with previously hegemonic myths about the American experience. How do their films negotiate expectations of genre? What happens to meaning when pastiche or appropriation become vital to the narrative and imaginary world of the films? We will watch up to a dozen films, including Fargo, No Country for Old Men, Miller's Crossing, O Brother Where art Thou and The Big Lebowski, not quite in chronological order,. Readings from scholarly and theoretical material, as well as excerpts from many of their sources, from Homer to Hammett. We'll also consider some of the 20th century painting, architecture and style that informs their films. Mandatory out of class viewings. (Theory, Intermedia)","cross_listed":["LIT 238W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/cnms-cinema-and-media-studies/200/cnms-238","sections":[{"days":"TR","room":null,"types":["Writing Intensive Courses"],"status":"waitlisted","section":"01","building":null,"capacity":18,"comments":"Open to Srs, Jrs, and Sophomores.","end_time":"15:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"15:45","start_date":"2027-01-20","start_time":"14:30"},{"days":"W","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"22:00","start_date":"2027-01-20","start_time":"19:00"}],"start_time":"14:30:00","instructors":["Stephen H. Schillinger"]}]},
{"code":"CNMS 243","title":"East Asian Women in Film","department":"Cinema and Media Studies","credits":1,"description":"This course examines portrayals of East Asian women in mainland Chinese, Hong Kong, Taiwanese, Japanese, Korean, and Hollywood films, with an emphasis on the post-#MeToo era. Through close analysis of narrative films and documentaries, students learn to investigate how gendered experiences of oppression, resilience, and resistance are represented, challenged, and reimagined in diverse cultural contexts. Combining film studies and gender studies, the course highlights both shared and divergent regional patterns and encourages students to consider how cinema shapes public debates on social change, agency, and justice. All films include English subtitles. Course requirements include film viewings, presentations, active discussion, a creative project, and a final paper.","cross_listed":["CHNSE 243"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/cnms-cinema-and-media-studies/200/cnms-243","sections":[{"days":"TR","room":null,"types":[],"status":"waitlisted","section":"01","building":null,"capacity":40,"comments":"Open to Srs., Jrs., Soph., & 1st Years.","end_time":"15:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"15:45","start_date":"2027-01-20","start_time":"14:30"}],"start_time":"14:30:00","instructors":["Zhuoyi Wang"]}]},
{"code":"CNMS 289","title":"Video Essays","department":"Cinema and Media Studies","credits":0.5,"description":"Videographic criticism is a multimodal form of writing. In using sound and image to comment on audiovisual texts, the video essay blurs the line between object and method of study. This hands-on humanities lab introduces students to a wide range of videographic techniques and formats, and some of the theoretical and philosophical concerns driving recent developments in the field. Students learn to not only craft their own video essays, but display greater reflexivity about their aesthetic choices, interventions and compositional process. No prior editing or other digital experience required.","cross_listed":["LIT 289"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/cnms-cinema-and-media-studies/200/cnms-289","sections":[{"days":"TR","room":null,"types":[],"status":"waitlisted","section":"02","building":null,"capacity":12,"comments":"0.5 credit course; Meets 1/20/27-3/12/27","end_time":"14:15:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-03-12","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Pavitra Sundar"]}]},
{"code":"CNMS 301","title":"Avant Garde Cinema","department":"Cinema and Media Studies","credits":1,"description":"A history of alternatives to commercial movies, focusing on surrealist and dadaist film, visual music, psychodrama, direct cinema, the film society movement, personal cinema, the New American Cinema, structuralism, Queer cinema, feminist cinema, minor cinema, recycled cinema and devotional cinema. While conventional entertainment films use the novel, the short story and the stage drama as their primary instigations, experimental and avant-garde films are analogous to music, poetry, painting, sculpture and collage. Not open to first-year students.","cross_listed":["ARTH 301","LIT 301"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/cnms-cinema-and-media-studies/300/cnms-301","sections":[{"days":"MW","room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":"Open to Seniors, Juniors, and Sophomores. First Years by instructor permission.","end_time":"22:00:00","meetings":[{"days":"MW","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"22:00","start_date":"2027-01-20","start_time":"19:00"}],"start_time":"19:00:00","instructors":["Scott M. MacDonald"]}]},
{"code":"CNMS 349","title":"Queer/Trans Cultural Produc","department":"Cinema and Media Studies","credits":1,"description":"This course explores queer and trans cultural production, ranging from zines, film, novels, photography, television, short fiction, painting, fanfiction, installation, poetry, performance art, music, video games, and more. On one level, it offers an interdisciplinary investigation of queer and trans representation, and both the possibilities and limitations of positive images and mainstream LGBTQ visibility. On another level, we explore the ways that writers, filmmakers, and artists find meaning through LGBTQ cultural production and artistic practices. We will also consider the politics of publication and distribution. The course takes up an intersectional approach, thinking about how LGBTQ cultural production is shaped by gender, race, ethnicity, nationality, class, and ability.","cross_listed":["WMGST 349"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/cnms-cinema-and-media-studies/300/cnms-349","sections":[{"days":"W","room":null,"types":[],"status":"open","section":"01","building":null,"capacity":12,"comments":null,"end_time":"16:00:00","meetings":[{"days":"W","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Amy Marvin"]}]},
{"code":"CNMS 428","title":"Post-war Cinematographic","department":"Cinema and Media Studies","credits":1,"description":"Based on three chapters of recent French history (the Occupation and the Holocaust; relationship with Algeria; May 1968 and social unrest), investigates how filmmakers mediate individual and national memories through moving images. The films will be considered in the context of recent historiographical material, theoretical discourse on cinema, and very specific cultural policies in France, as well as popular events around cinema. Includes about 10 movies. Some Friday afternoons will be reserved for film screenings. Taught in French.","cross_listed":["FRNCH 428"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/cnms-cinema-and-media-studies/400/cnms-428","sections":[{"days":"TR","room":null,"types":[],"status":"waitlisted","section":"01","building":null,"capacity":12,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"11:45","start_date":"2027-01-20","start_time":"10:30"}],"start_time":"10:30:00","instructors":["Martine Guyot-Bender"]}]},
{"code":"CNMS 550","title":"Senior Honors Project","department":"Cinema and Media Studies","credits":1,"description":"The Senior Honors project in Cinema and Media studies allows students the opportunity to demonstrate independence, maturity and mastery as emerging scholars and/or media producers. Honors projects require a written proposal or abstract with an annotated bibliography signed by the student's proposed advisor. The director in consultation with the CMS faculty will approve proposals and assign a second faculty member to the student's advisory committee. Prerequisites, Consent of Instructor.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/cnms-cinema-and-media-studies/500/cnms-550","sections":[{"days":null,"room":null,"types":["Senior Project"],"status":"open","section":"01","building":null,"capacity":12,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Scott M. MacDonald"]}]},
{"code":"COLEG 106","title":"What Is AI?","department":"College Courses","credits":1,"description":"A hands-on first class in artificial intelligence, with no prerequisite knowledge of computer science or mathematics required. The course will cover the technical aspects, as well as the history, ethical implications, and societal impacts of artificial intelligence. Topics will span both the theory and practice underlying modern AI. Class is discussion heavy, consists of many hands-on projects and a synthesis project of the student's own design.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/coleg-college-courses-and-seminars/100/coleg-106","sections":[{"days":"MWF","room":null,"types":[],"status":"waitlisted","section":"01","building":null,"capacity":40,"comments":"Open to Srs., Jrs., Soph., & 1st Yr","end_time":"11:50:00","meetings":[{"days":"MWF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"11:50","start_date":"2027-01-20","start_time":"11:00"}],"start_time":"11:00:00","instructors":["Vikranth Bejjanki","Justin C. Clark","Christina Ji","Jaime L. Kucinskas","Darren J. Strash","Erin E. Tripp"]}]},
{"code":"COLEG 223","title":"Gender&violence Middle Ages","department":"College Courses","credits":1,"description":"An introduction to the field of medieval and renaissance studies. Drawing on multiple disciplinary perspectives, including those of literature, law, history and art, examines the intersection of ideas about the body, gender and violence in the European Middle Ages. Readings may include the Bible and early patristic writings; the lives of saints; poems and advice manuals on courtly love; depictions of women in the Crusades; Icelandic sagas; and perspectives on the trial of Joan of Arc. Prerequisites, one 100-level course in literature or history, or AP 4 or 5 in English or History.","cross_listed":["HIST 223","LIT 223","MDRST 223"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/coleg-college-courses-and-seminars/200/coleg-223","sections":[{"days":"MWF","room":null,"types":["Diversity Course"],"status":"open","section":"01","building":null,"capacity":24,"comments":"Open to 1st Yrs, Soph. & Jrs. Only","end_time":"09:50:00","meetings":[{"days":"MWF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"09:50","start_date":"2027-01-20","start_time":"09:00"}],"start_time":"09:00:00","instructors":["John T. Eldevik","Katherine H. Terrell"]}]},
{"code":"COLEG 239","title":"Digital Human Rights","department":"College Courses","credits":1,"description":"Research based on Open Source Intelligence (OSINT) is a technique pioneered by non-profit organizations and academic institutions to improve the transparency and fact-checking of investigative journalism and strengthen legal cases in the area of international human rights. This course provides students with an overview of these techniques and considers associated ethical, privacy, and technological concerns. Students will use techniques learned in class to gather and analyze OSINT materials related to international human rights violations in the context of the Russo-Ukrainian War. There is a required field trip to Washington, D.C., which involves staying overnight.","cross_listed":["GOVT 239"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/coleg-college-courses-and-seminars/200/coleg-239","sections":[{"days":"M","room":null,"types":["Experiential Learning"],"status":"waitlisted","section":"01","building":null,"capacity":12,"comments":"Open to Juniors and Seniors Only","end_time":"12:00:00","meetings":[{"days":"M","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"12:00","start_date":"2027-01-20","start_time":"09:00"}],"start_time":"09:00:00","instructors":["Sharon W. Rivera"]}]},
{"code":"COLEG 281","title":"Common Ground","department":"College Courses","credits":1,"description":"Examination of the U.S. Constitution through extended role-playing games in a speaking intensive course. Students immerse themselves in two constitutional moments - the 1787 Constitution Convention and a hypothetical new Convention of the States to propose new amendments to the U.S. Constitution.","cross_listed":["GOVT 281","HIST 281"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/coleg-college-courses-and-seminars/200/coleg-281","sections":[{"days":"TR","room":null,"types":["Co-Lab Course","Experiential Learning","Speaking Intensive Course"],"status":"open","section":"01","building":null,"capacity":20,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"11:45","start_date":"2027-01-20","start_time":"10:30"}],"start_time":"10:30:00","instructors":["Ty Seidule"]}]},
{"code":"COLEG 395","title":"NYC: Auxiliary/Practicum","department":"College Courses","credits":1,"description":"Topic changes each term to reflect the discipline of the director of the Program in New York City. Many resident directors use College 395 as a practicum in which the group takes field trips, or guest speakers join the class, or the class screens documentaries. For a more specific description, see www.hamilton.edu/academics/programs_abroad/nyc/. May include fieldwork. May count toward the concentration in the department or program of the director. Open only to program participants. May be repeated once for credit.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/coleg-college-courses-and-seminars/300/coleg-395","sections":[{"days":null,"room":null,"types":[],"status":"open","section":"01","building":null,"capacity":20,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Nigel D. Westmaas"]}]},
{"code":"COLEG 396","title":"NYC: Indep Study","department":"College Courses","credits":1,"description":"An independent study supervised by the director of the Program in New York City and based on an internship and additional research. For a more specific description, see www.hamilton.edu/academics/programs_abroad/nyc/. May count toward the concentration or minor in the department or program of the director. Open only to program participants. May be repeated once for credit.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/coleg-college-courses-and-seminars/300/coleg-396","sections":[{"days":null,"room":null,"types":["Experiential Learning"],"status":"open","section":"01","building":null,"capacity":20,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Nigel D. Westmaas"]}]},
{"code":"COLEG 397","title":"NYC: Internship","department":"College Courses","credits":1,"description":"Internship with firm, organization, agency or advocacy group appropriate to the theme of the semester. For more information, see www.hamilton.edu/academics/programs_abroad/nyc/. Does not count toward concentration credit. Open only to program participants. May be repeated once for credit.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/coleg-college-courses-and-seminars/300/coleg-397","sections":[{"days":null,"room":null,"types":["Experiential Learning"],"status":"open","section":"01","building":null,"capacity":16,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Nigel D. Westmaas"]}]},
{"code":"COLEG 398","title":"NYC: Anchor Seminar","department":"College Courses","credits":1,"description":"Foundational course of the program in New York City, organized around the semester's designated theme. See www.hamilton.edu/academics/programs_abroad/nyc/ for the semester's focus. May count toward concentration credit in the designated departments. Open only to program participants. May be repeated once for credit.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/coleg-college-courses-and-seminars/300/coleg-398","sections":[{"days":null,"room":null,"types":[],"status":"open","section":"01","building":null,"capacity":16,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Nigel D. Westmaas"]}]},
{"code":"CPSCI 101","title":"Computer Science for All","department":"Computer Science","credits":1,"description":"The first course in computer science is an introduction to algorithmic problem-solving using the Python programming language. Topics include primitive data types, mathematical operations, structured programming with conditional and iterative idioms, functional abstraction, and objects. Students apply these skills in writing programs to solve problems in domains across the liberal arts. No previous programming experience necessary. Three hours of lecture and two hours of laboratory.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/cpsci-computer-science/100/cpsci-101","sections":[{"days":"MWF","room":null,"types":["Quantitative & Symbolic R"],"status":"open","section":"01","building":null,"capacity":40,"comments":"Open to Srs., Jrs., Soph., & 1st Yrs. Instructor's signature required during schedule adjustment.","end_time":"09:50:00","meetings":[{"days":"MWF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"09:50","start_date":"2027-01-20","start_time":"09:00"}],"start_time":"09:00:00","instructors":["Christina Ji"]}]},
{"code":"CPSCI 101L","title":"Computer Science for All Lab","department":"Computer Science","credits":0,"description":null,"cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/cpsci-computer-science/100/cpsci-101","sections":[{"days":"M","room":null,"types":[],"status":"waitlisted","section":"01","building":null,"capacity":20,"comments":"Open to Srs., Jrs., Soph., & 1st Yrs. Instructor's signature required during schedule adjustment.","end_time":"16:00:00","meetings":[{"days":"M","room":null,"type":"LAB","building":null,"end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"14:00"}],"start_time":"14:00:00","instructors":["Han Dong"]},{"days":"T","room":null,"types":[],"status":"open","section":"02","building":null,"capacity":20,"comments":"Open to Srs., Jrs., Soph., & 1st Yrs. Instructor's signature required during schedule adjustment.","end_time":"16:00:00","meetings":[{"days":"T","room":null,"type":"LAB","building":null,"end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"14:00"}],"start_time":"14:00:00","instructors":["Han Dong"]}]},
{"code":"CPSCI 102","title":"Design Principles","department":"Computer Science","credits":1,"description":"A second course in programming, concentrating on principled software design techniques. Topics include class design, effective functional decomposition, recursion, and structured data. Students will continue to develop programming proficiency by writing programs in the C++ programming language. Course discussion will emphasize, efficient implementations in terms of memory space and running time, computational complexity of algorithms, and an introduction to data structures. Three hours of lecture and two hours of laboratory.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/cpsci-computer-science/100/cpsci-102","sections":[{"days":"MWF","room":null,"types":["Quantitative & Symbolic R"],"status":"open","section":"01","building":null,"capacity":40,"comments":"Students must also register for a section of CPSCI 102 lab. Open to First Years and Sophomores only during registration. Remaining seats will be made available to Juniors and Seniors during Schedule Adjustment.","end_time":"11:50:00","meetings":[{"days":"MWF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"11:50","start_date":"2027-01-20","start_time":"11:00"}],"start_time":"11:00:00","instructors":["Sarah Morrison-Smith"]}]},
