{"code":"CRWR 419","title":"Seminar Creative Writing","department":"Creative Writing","credits":1,"description":"For students whose work and purpose have developed sufficiently to warrant advanced work in fiction or poetry. Students will construct individual projects leading to a final collection of writings in the form of a novella, a series of stories, or a series of poems. Regular writing and reading assignments, as well as critiques in class. Open only to senior concentrators and, if there is room, senior minors.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/crwr-creative-writing/400/crwr-419","sections":[{"days":"W","room":null,"types":[],"status":"waitlisted","section":"01","building":null,"capacity":7,"comments":"Restricted CRWR Majors Only","end_time":"16:00:00","meetings":[{"days":"W","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Patrick Joseph Caoile"]},{"days":"R","room":null,"types":[],"status":"waitlisted","section":"02","building":null,"capacity":7,"comments":"Restricted CRWR Majors Only","end_time":"16:00:00","meetings":[{"days":"R","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Anne E. Valente"]},{"days":"T","room":null,"types":[],"status":"open","section":"03","building":null,"capacity":7,"comments":"Restricted to CRWR Majors Only","end_time":"16:00:00","meetings":[{"days":"T","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Jane E. Springer"]}]},
{"code":"DANCE 112","title":"Elementary Dance","department":"Dance","credits":1,"description":"Studio-based course that introduces students to concepts and techniques of contemporary dance. Emphasizes movement articulation, kinesthetic awareness, and originality. Alongside developing movement fluency, students will learn to analyze and situate contemporary dance within historical and cultural contexts. The course explores how technique reflects cultural values and considers the frameworks through which we understand dancing bodies. No previous dance training required.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/dance-dance-and-movement-studies/100/dance-112","sections":[{"days":"TR","room":"101","types":["Soc, Struct & Inst Hier"],"status":"waitlisted","section":"01","building":"Blood Fitness Center","capacity":25,"comments":"Open to Srs, Jrs, Soph, and 1st Yrs","end_time":"11:45:00","meetings":[{"days":"TR","room":"101","type":"LEC","building":"Blood Fitness Center","end_date":"2027-05-11","end_time":"11:45","start_date":"2027-01-20","start_time":"10:30"}],"start_time":"10:30:00","instructors":["Casey E. Avaunt"]}]},
{"code":"DANCE 114","title":"Elementary Ballet","department":"Dance","credits":1,"description":"Beginner-level study of classical ballet with a focus on ballet's basic vocabulary in both barre and center floor exercises, studio-stage directions and designations for the classical positions of the body in space. Work on such stylistic aspects of ballet as musicality, dynamics and use of the head. Readings in kinesiology pertaining to muscular alignment analysis. No previous dance experience required.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/dance-dance-and-movement-studies/100/dance-114","sections":[{"days":"TR","room":"101","types":[],"status":"waitlisted","section":"01","building":"Blood Fitness Center","capacity":25,"comments":"Open to Srs., Jrs., Soph., & 1st Yrs.","end_time":"10:15:00","meetings":[{"days":"TR","room":"101","type":"LEC","building":"Blood Fitness Center","end_date":"2027-05-11","end_time":"10:15","start_date":"2027-01-20","start_time":"09:00"}],"start_time":"09:00:00","instructors":["Paris Wilcox"]}]},
{"code":"DANCE 142","title":"Performance","department":"Dance","credits":0.25,"description":"The study of dance through performance of a role in a main stage dance concert.","cross_listed":[],"catalog_url":null,"sections":[{"days":null,"room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":"Instructor's signature required","end_time":null,"meetings":[],"start_time":null,"instructors":["Casey E. Avaunt"]},{"days":null,"room":null,"types":[],"status":"open","section":"02","building":null,"capacity":40,"comments":"Instructor's signature required","end_time":null,"meetings":[],"start_time":null,"instructors":["Nikolas C. Owens"]},{"days":null,"room":null,"types":[],"status":"open","section":"03","building":null,"capacity":40,"comments":"Instructor's signature required","end_time":null,"meetings":[],"start_time":null,"instructors":["Paris Wilcox"]},{"days":null,"room":null,"types":[],"status":"open","section":"04","building":null,"capacity":40,"comments":"Instructor's signture required","end_time":null,"meetings":[],"start_time":null,"instructors":["Melissa Larish"]}]},
{"code":"DANCE 159","title":"Elementary Jazz Dance","department":"Dance","credits":1,"description":"An introductory technique course exploring jazz dance as a form grounded in Black American cultural and performance traditions. Students develop foundational skills in rhythm, coordination, and jazz vocabulary while situating studio practice within the historical evolution of jazz dance. Attention is given to stylistic nuance, musicality, and expressive range within jazz movement. Open to all students; no previous dance experience required.","cross_listed":["AFRST 159"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/dance-dance-and-movement-studies/100/dance-159","sections":[{"days":"MW","room":"101","types":["Soc, Struct & Inst Hier"],"status":"waitlisted","section":"01","building":"Blood Fitness Center","capacity":25,"comments":"Open to Srs., Jrs., Soph., & 1st Yr","end_time":"09:45:00","meetings":[{"days":"MW","room":"101","type":"LEC","building":"Blood Fitness Center","end_date":"2027-05-11","end_time":"09:45","start_date":"2027-01-20","start_time":"08:30"}],"start_time":"08:30:00","instructors":["Nikolas C. Owens"]}]},
{"code":"DANCE 203","title":"Movement and Meaning","department":"Dance","credits":1,"description":"This course explores the moving body through multiple perspectives, examining how movement is shaped by personal experience, culture, and society. Drawing on philosophical and dance studies approaches, students consider movement as physical action while also attending to its expressive and cultural significance. Through experiential movement work, readings, written reflections, discussions, and presentations, students develop skills in observing, experiencing, and analyzing movement. Alongside this analytical work, the course emphasizes developing a stronger connection to one's own body through physical exercises that support embodied awareness and healthy movement practices. No prior dance training required.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/dance-dance-and-movement-studies/200/dance-203","sections":[{"days":"TR","room":"101","types":[],"status":"waitlisted","section":"01","building":"Blood Fitness Center","capacity":15,"comments":null,"end_time":"14:15:00","meetings":[{"days":"TR","room":"101","type":"LEC","building":"Blood Fitness Center","end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Casey E. Avaunt"]}]},
{"code":"DANCE 213","title":"Interm. Contemp Dance&theory","department":"Dance","credits":1,"description":"The study of contemporary dance incorporating technique and theory. Emphasis on alignment and efficiency of movement focusing on increasing strength and flexibility. May be repeated for credit. Prerequisites, Dance 112, 113, or 114 or permission of instructor.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/dance-dance-and-movement-studies/200/dance-213","sections":[{"days":"MW","room":"101","types":[],"status":"open","section":"01","building":"Blood Fitness Center","capacity":25,"comments":"Open to Srs., Jrs., Sophomores, & 1st Yrs","end_time":"14:15:00","meetings":[{"days":"MW","room":"101","type":"LEC","building":"Blood Fitness Center","end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Nikolas C. Owens"]}]},
{"code":"DANCE 215","title":"Intermediate Ballet","department":"Dance","credits":1,"description":"Continuation of the study of ballet. Technique classes are combined with studies in kinesiology, dance theory and dance criticism. May be repeated for credit. Prerequisites, 114, or consent of instructor.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/dance-dance-and-movement-studies/200/dance-215","sections":[{"days":"MWF","room":"101","types":[],"status":"open","section":"01","building":"Blood Fitness Center","capacity":25,"comments":"Open to Srs., Jrs., Soph., & 1st Yrs.","end_time":"12:15:00","meetings":[{"days":"MWF","room":"101","type":"LEC","building":"Blood Fitness Center","end_date":"2027-05-11","end_time":"12:15","start_date":"2027-01-20","start_time":"11:00"}],"start_time":"11:00:00","instructors":["Melissa Larish"]}]},
{"code":"DANCE 307","title":"Making Dance II","department":"Dance","credits":1,"description":"An intermediate choreographic course centered on the craft of composition: space, time, structure, texture, and dynamics. Through sustained studio practice, students will generate, organize, and refine movement material, exploring how compositional choices shape the experience of a dance. The course includes close study of professional choreography to inform students' creative processes. It culminates in each student presenting a fully realized original dance work.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/dance-dance-and-movement-studies/300/dance-307","sections":[{"days":"MW","room":"101","types":[],"status":"open","section":"01","building":"Blood Fitness Center","capacity":25,"comments":null,"end_time":"15:45:00","meetings":[{"days":"MW","room":"101","type":"LEC","building":"Blood Fitness Center","end_date":"2027-05-11","end_time":"15:45","start_date":"2027-01-20","start_time":"14:30"}],"start_time":"14:30:00","instructors":["Casey E. Avaunt"]}]},
{"code":"DANCE 560","title":"Senior Perf.&productn","department":"Dance","credits":1,"description":"A performance of dance works, the choreography of dance works or both. Substantial written component comprising research into the historical, theoretical and socio-cultural contexts of the chosen work. Following submission of the monograph and completion of production, each student will participate in the evaluation of her/his project with an evaluating committee. Open to senior concentrators only.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/dance-dance-and-movement-studies/500/dance-560","sections":[{"days":null,"room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":"Open to Seniors Only.","end_time":null,"meetings":[],"start_time":null,"instructors":["Casey E. Avaunt"]}]},
{"code":"DARTS 113","title":"Intro to Media:integrated Med","department":"Digital Arts","credits":1,"description":"This course will serve as an introduction to digital technology in contemporary art making as it relates to interactivity, collaboration, and emerging practices. Emphasis will be placed on hands on experimentation and exploration across disciplines. We will cover installation art, web art, digital and time-based art, and immersive environments. Students will gain an overview of emerging digital practices, collaborative production strategies and correlations to social, aesthetic and theoretical issues. Other topics may include virtuality, performance, cyborgs, and network culture.","cross_listed":["ART 113","MUSIC 113"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/darts-digital-arts/100/darts-113","sections":[{"days":"F","room":"143","types":[],"status":"open","section":"01","building":"Kennedy Center Theatre/Arts","capacity":16,"comments":"Open to 1st Yrs, Soph., & Jrs.","end_time":"16:00:00","meetings":[{"days":"F","room":"143","type":"STU","building":"Kennedy Center Theatre/Arts","end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"13:00"},{"days":"F","room":"124","type":"STU","building":"Kennedy Center Theatre/Arts","end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Anna Huff"]}]},
{"code":"DARTS 231","title":"Intermed Media: New Frontiers","department":"Digital Arts","credits":1,"description":"This class will survey and create emergent and non -linear forms of storytelling using digital and hybrid tools. We will examine notions of narrative authority and hybridity in a digital age and think through different ways we might use technology to distill, break apart or reify modes of communication and visual metaphor. Discussion will push boundaries of traditional storytelling and consider connectivity, liveness and embodied presence. This course will draw on multiple forms of expression including but not limited to digital media, performance, sound, XR, web and network environments.","cross_listed":["MUSIC 231","THETR 231"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/darts-digital-arts/200/darts-231","sections":[{"days":"R","room":"143","types":[],"status":"open","section":"01","building":"Kennedy Center Theatre/Arts","capacity":16,"comments":null,"end_time":"16:00:00","meetings":[{"days":"R","room":"143","type":"STU","building":"Kennedy Center Theatre/Arts","end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"13:00"},{"days":"R","room":"124","type":"STU","building":"Kennedy Center Theatre/Arts","end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Anna Huff"]}]},
{"code":"ECON 100","title":"Introduction to Economics","department":"Economics","credits":1,"description":"The price system as a mechanism for determining which goods will be produced and which inputs employed; decision-making by firms and individuals; market structure; Gross domestic product; its measurement and the determination of production and employment levels; the role of the government in the economy. Not open to seniors.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/econ-economics/100/econ-100","sections":[{"days":"MWF","room":null,"types":["Quantitative & Symbolic R"],"status":"open","section":"01","building":null,"capacity":40,"comments":"Open to 1st Yrs, Soph. & Jrs. Only Exclude Econ 101 & 102.","end_time":"09:50:00","meetings":[{"days":"MWF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"09:50","start_date":"2027-01-20","start_time":"09:00"}],"start_time":"09:00:00","instructors":["Evelyn E. Skoy"]},{"days":"MWF","room":null,"types":["Quantitative & Symbolic R"],"status":"open","section":"02","building":null,"capacity":40,"comments":"Open to 1st Yrs, Soph. & Jrs. Only Exclude Econ 101 & 102.","end_time":"10:50:00","meetings":[{"days":"MWF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"10:50","start_date":"2027-01-20","start_time":"10:00"}],"start_time":"10:00:00","instructors":["Evelyn E. Skoy"]}]},
{"code":"ECON 166","title":"Econ Theory & Evidence","department":"Economics","credits":1,"description":"An introduction to how economists develop and test theory, with a special emphasis on theory explaining the causes and consequences of inequality. The basic concepts of probability and statistics are taught in addition to theories of the labor market, inflation/unemployment tradeoffs, impact of fiscal and monetary policy, externalities, public goods, and international trade. Not open to seniors or students who have taken Math 152 or Math 252 or Math 253 or Math 254 or Math 352. Students who have taken Govt 230 may not register for Econ 166 without permission of the instructor.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/econ-economics/100/econ-166","sections":[{"days":"MW","room":null,"types":["Co-Lab Course","Quantitative & Symbolic R"],"status":"waitlisted","section":"01","building":null,"capacity":40,"comments":"Open to 1st Yrs, Soph. & Jrs. Only Exclude Math 253 & 352 & 152/252 This section of ECON 166 is part of the Spring 2027 Justice Lab (shared enrollment).","end_time":"14:15:00","meetings":[{"days":"MW","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Ann Owen"]},{"days":"MW","room":null,"types":["Quantitative & Symbolic R"],"status":"open","section":"02","building":null,"capacity":40,"comments":"Open to 1st Yrs, Soph. & Jrs. Only Exclude Math 253 & 352 & 152/252","end_time":"15:45:00","meetings":[{"days":"MW","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"15:45","start_date":"2027-01-20","start_time":"14:30"}],"start_time":"14:30:00","instructors":["Ann Owen"]},{"days":"MWF","room":null,"types":["Quantitative & Symbolic R"],"status":"waitlisted","section":"03","building":null,"capacity":40,"comments":"Open to 1st Yrs, Soph. & Jrs. Only Exclude Math 253 & 352 & 152/252.","end_time":"10:50:00","meetings":[{"days":"MWF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"10:50","start_date":"2027-01-20","start_time":"10:00"}],"start_time":"10:00:00","instructors":["Promise Kamanga"]},{"days":"MWF","room":null,"types":["Quantitative & Symbolic R"],"status":"waitlisted","section":"04","building":null,"capacity":40,"comments":"Open to 1st Yrs, Soph. & Jrs. Only","end_time":"11:50:00","meetings":[{"days":"MWF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"11:50","start_date":"2027-01-20","start_time":"11:00"}],"start_time":"11:00:00","instructors":["Promise Kamanga"]}]},
{"code":"ECON 266","title":"Intro to Econometrics","department":"Economics","credits":1,"description":"An introduction to econometric methods that are frequently used in applied economic research. Emphasis on interpreting and critically evaluating empirical results and on establishing the statistical foundations of widely used econometric methods. Topics include the classical linear regression model, functional form, dummy explanatory variables, binary choice models, panel data models, instrumental variables and time series models. Three hours of class and 75 minutes of laboratory. Not open to seniors or students who have taken Econ 400.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/econ-economics/200/econ-266","sections":[{"days":"TR","room":null,"types":["Quantitative & Symbolic R"],"status":"waitlisted","section":"01","building":null,"capacity":20,"comments":"Open to 1st Yrs, Soph. & Jrs. Only. Not open to those who took ECON 400. Juniors must be ECON concentrator.","end_time":"10:15:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"10:15","start_date":"2027-01-20","start_time":"09:00"},{"days":"R","room":null,"type":"LAB","building":null,"end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"09:00:00","instructors":["Jeffrey R. Cross"]},{"days":"TR","room":null,"types":["Quantitative & Symbolic R"],"status":"open","section":"02","building":null,"capacity":20,"comments":"Open to 1st Yrs, Soph. & Jrs. Only. Not open to those who took ECON 400. Juniors must be ECON concentrator.","end_time":"10:15:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"10:15","start_date":"2027-01-20","start_time":"09:00"},{"days":"R","room":null,"type":"LAB","building":null,"end_date":"2027-05-11","end_time":"15:45","start_date":"2027-01-20","start_time":"14:30"}],"s