{"code":"NEURO 198","title":"Collaborative Research","department":"Neuroscience","credits":0.25,"description":"Collaborative research under the supervision of a faculty member. Focus on data collection and/or analysis. Three to four hours per week of lab work. Prerequisites, Permission of the instructor. Student performance will be evaluated as Satisfactory/Unsatisfactory. One-quarter credit per semester. May be repeated for credit, but does not count toward concentration requirements.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/neuro-neuroscience/100/neuro-198","sections":[{"days":null,"room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":"Instructor's Signature Req.","end_time":null,"meetings":[],"start_time":null,"instructors":["Alexandra List"]},{"days":null,"room":null,"types":[],"status":"open","section":"02","building":null,"capacity":40,"comments":"Instructor's Signature Req.","end_time":null,"meetings":[],"start_time":null,"instructors":["Siobhan Robinson"]},{"days":null,"room":null,"types":[],"status":"open","section":"03","building":null,"capacity":40,"comments":"Instructor's Signature Req.","end_time":null,"meetings":[],"start_time":null,"instructors":["Abigail K. Myers"]},{"days":null,"room":null,"types":[],"status":"open","section":"04","building":null,"capacity":40,"comments":"Instructor's Signature Required","end_time":null,"meetings":[],"start_time":null,"instructors":["Kelly E. Faig"]},{"days":null,"room":null,"types":[],"status":"open","section":"05","building":null,"capacity":40,"comments":"Instructor's Signature Required","end_time":null,"meetings":[],"start_time":null,"instructors":["Vikranth Bejjanki"]},{"days":null,"room":null,"types":[],"status":"open","section":"06","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Lok-Kin Yeung"]},{"days":null,"room":null,"types":[],"status":"op