{"code":"NEURO 201","title":"Stats & Research Methods","department":"Neuroscience","credits":1,"description":"The application and interpretation of descriptive and inferential statistics in the study of psychological processes. Some instruction in research design and methodological issues. Students will learn to use the statistical computer program SPSS to analyze data. Topics include the principles of hypothesis testing, t tests, analysis of variance, regression, and some non-parametric statistics. Prerequisites, 101.","cross_listed":["PSYCH 201"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/neuro-neuroscience/200/neuro-201","sections":[{"days":"MWF","room":null,"types":["Qlit Course","Quantitative & Symbolic R"],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":"10:50:00","meetings":[{"days":"MWF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"10:50","start_date":"2027-01-20","start_time":"10:00"}],"start_time":"10:00:00","instructors":["Siobhan Robinson"]},{"days":"MWF","room":null,"types":["Qlit Course","Quantitative & Symbolic R"],"status":"open","section":"02","building":null,"capacity":40,"comments":null,"end_time":"11:50:00","meetings":[{"days":"MWF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"11:50","start_date":"2027-01-20","start_time":"11:00"}],"start_time":"11:00:00","instructors":["Siobhan Robinson"]}]},
{"code":"NEURO 204","title":"Human Neuroscience","department":"Neuroscience","credits":1,"description":"Introduction to the field of neuroscience from a behavioral and cognitive perspective. Survey of experimental and clinical research involving humans and non-human animals, addressing presumed neural mechanisms for cognitive, motivational and emotional states. Analysis of amnesia, aphasia, agnosias, apraxias and disconnection syndromes.","cross_listed":["PSYCH 204"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/neuro-neuroscience/200/neuro-204","sections":[{"days":"TR","room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":"10:15:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"10:15","start_date":"2027-01-20","start_time":"09:00"}],"start_time":"09:00:00","instructors":["Alexandra List"]},{"days":"TR","room":null,"types":[],"status":"open","section":"02","building":null,"capacity":40,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"11:45","start_date":"2027-01-20","start_time":"10:30"}],"start_time":"10:30:00","instructors":["Alexandra List"]}]},
{"code":"NEURO 211","title":"Genes, Molecules, & Cells","department":"Neuroscience","credits":1,"description":"An intermediate course that examines genetics and biochemistry within the context of the cell. This course will focus on the macromolecules of life, genetic material and classical genetics, fundamental biochemical pathways, and cellular structure and function. A particular focus will be placed on proteins and nucleic acids and how cells use these molecules to direct the mechanisms of inheritance, energy production, and cellular reproduction. Three hours of class and three hours of laboratory.","cross_listed":["BIO 211"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/neuro-neuroscience/200/neuro-211","sections":[{"days":"TR","room":null,"types":["Quantitative & Symbolic R"],"status":"waitlisted","section":"01","building":null,"capacity":30,"comments":"Open to 1st Yrs and Sophomores only. Not open to those who took BIO 248 or BIO 249.","end_time":"11:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"11:45","start_date":"2027-01-20","start_time":"10:30"}],"start_time":"10:30:00","instructors":["Rhea R. Datta"]},{"days":"TR","room":null,"types":["Quantitative & Symbolic R"],"status":"open","section":"02","building":null,"capacity":30,"comments":null,"end_time":"10:15:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"10:15","start_date":"2027-01-20","start_time":"09:00"}],"start_time":"09:00:00","instructors":["Ivan Bochkov"]}]},
