{"code":"PHYS 298","title":"Physics Research","department":"Physics","credits":0.25,"description":"Independent work on a research project under supervision of a faculty member. Prerequisites, Consent of instructor. One-quarter or one-half credit per semester. Satisfactory/Unsatisfactory only. Students may repeat 298 for credit, but only a maximum of one-half credit of Physics Research can count towards their concentration.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/phys-physics/200/phys-298","sections":[{"days":null,"room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Katherine A. Brown"]},{"days":null,"room":null,"types":[],"status":"open","section":"02","building":null,"capacity":40,"comments":"Instructor's signature required.","end_time":null,"meetings":[],"start_time":null,"instructors":["Gordon L. Jones"]},{"days":null,"room":null,"types":[],"status":"open","section":"03","building":null,"capacity":40,"comments":"Instructor's Signature Required","end_time":null,"meetings":[],"start_time":null,"instructors":["Seth A. Major"]},{"days":null,"room":null,"types":[],"status":"open","section":"04","building":null,"capacity":40,"comments":"Instructor's Signature Req.","end_time":null,"meetings":[],"start_time":null,"instructors":["Viva R. Horowitz"]}]},
{"code":"PHYS 320","title":"Topic Mathematical Phys","department":"Physics","credits":1,"description":"A study of mathematical methods and their use in investigating physical systems. Topics may include ordinary differential equations, special functions, Sturm-Liouville theory, partial differential equations, integral transforms, calculus of complex functions, numerical methods, tensor analysis, and group theory.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/phys-physics/300/phys-320","sections":[{"days":"TR","room":"G047","types":["Quantitative & Symbolic R"],"status":"open","section":"01","building":"Taylor Science Center","capacity":40,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":"G047","type":"LEC","building":"Taylor Science Center","end_date":"2027-05-11","end_time":"11:45","start_date":"2027-01-20","start_time":"10:30"}],"start_time":"10:30:00","instructors":["Ariel Rock"]}]},
{"code":"PHYS 340","title":"Topics in Quantum Physics","department":"Physics","credits":1,"description":"Exploration of topics in contemporary physics using the tools of quantum mechanics developed in PHYS 290. Topics may include multi-electron atoms, molecules, solid state physics, lasers and quantum optics, nuclear physics, quantum computing, and particle physics. Prerequisites, 290.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/phys-physics/300/phys-340","sections":[{"days":"MWF","room":null,"types":["Quantitative & Symbolic R"],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":"15:20:00","meetings":[{"days":"MWF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"15:20","start_date":"2027-01-20","start_time":"14:30"}],"start_time":"14:30:00","instructors":["Wren Vetens"]}]},
{"code":"PHYS 348","title":"Sci, Technology & Society","department":"Physics","credits":0.5,"description":"An examination of the assumptions, paradigms, and hierarchies embedded in science and technology. This course will examine evidence pointing to the structure of hierarchies built into and from science and how those structures may result in inequalities for various groups participating in and affected by science and technology. Topics will vary but might include: the objectivity/subjectivity of science; how biases and social structures intersect with equity, diversity, and inclusion in science; and gender and race disparities in STEM fields.","cross_listed":["CHEM 348"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/phys-physics/300/phys-348","sections":[{"days":"WF","room":null,"types":["Soc, Struct & Inst Hier"],"status":"open","section":"01","building":null,"capacity":40,"comments":"Restricted to CHEM and PHYS majors. 0.5 credit class; Runs from 1/20/27 to 3/12/27.","end_time":"14:15:00","meetings":[{"days":"WF","room":null,"type":"LEC","building":null,"end_date":"2027-03-12","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Karen S. Brewer"]}]},
{"code":"PHYS 349","title":"Physics and Society II","department":"Physics","credits":0.5,"description":"A continuation of PHYS/CHEM 348, focused on applying the general material learned in PHYS/CHEM 348 to real life intersections of physics activities and broader society. In addition to an in-depth case study, students will complete projects using their knowledge of social, structural, and institutional hierarchies to improve the Physics Department. This is a half credit continuation of PHYS/CHEM 348 into the second half of the semester.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/phys-physics/300/phys-349","sections":[{"days":"WF","room":null,"types":["Soc, Struct & Inst Hier"],"status":"open","section":"01","building":null,"capacity":40,"comments":"0.5 credit course; Runs 3/29/27 through 5/17/27","end_time":"14:15:00","meetings":[{"days":"WF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"14:15","start_date":"2027-03-29","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Megan D. Smith"]}]},
{"code":"PHYS 390W","title":"Research Seminar","department":"Physics","credits":1,"description":"A series of research projects stressing the integration of theory and experiment. Emphasis on scientific writing, formal oral presentations, use of the current physics literature.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/phys-physics/300/phys-390","sections":[{"days":"MWF","room":"G029","types":["Quantitative & Symbolic R","Writing Intensive Courses"],"status":"open","section":"01","building":"Taylor Science Center","capacity":12,"comments":null,"end_time":"11:50:00","meetings":[{"days":"MWF","room":"G029","type":"LEC","building":"Taylor Science Center","end_date":"2027-05-11","end_time":"11:50","start_date":"2027-01-20","start_time":"11:00"}],"start_time":"11:00:00","instructors":["Brian Collett"]}]},
{"code":"PHYS 480","title":"Electromagnetic Theory","department":"Physics","credits":1,"description":"Intensive study of Maxwell's equations in both differential and integral form; electrostatics and electro-dynamics; special relativity; and the transformation of electromagnetic fields. Introduction to electromagnetic waves and dielectric and magnetic materials.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/phys-physics/400/phys-480","sections":[{"days":"MWF","room":"G029","types":["Quantitative & Symbolic R"],"status":"waitlisted","section":"01","building":"Taylor Science Center","capacity":12,"comments":null,"end_time":"10:50:00","meetings":[{"days":"MWF","room":"G029","type":"LEC","building":"Taylor Science Center","end_date":"2027-05-11","end_time":"10:50","start_date":"2027-01-20","start_time":"10:00"}],"start_time":"10:00:00","instructors":["Brian Collett"]}]},
{"code":"PHYS 550","title":"Senior Research Project","department":"Physics","credits":1,"description":"Independent research in collaboration with faculty supervisor. Students will give a series of formal oral presentations about their research and will write a comprehensive thesis. Open to senior concentrators or to others with consent of instructor.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/phys-physics/500/phys-550","sections":[{"days":"R","room":null,"types":["Senior Project"],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":"17:00:00","meetings":[{"days":"R","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"17:00","start_date":"2027-01-20","start_time":"14:30"}],"start_time":"14:30:00","instructors":["Adam C. Lark"]}]},
{"code":"PHYS 551","title":"Senior Research","department":"Physics","credits":1,"description":"Independent research in collaboration with faculty supervisor. Students will give a series of formal oral presentations about their research and will write a comprehensive thesis. Prerequisites, Phys 550.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/phys-physics/500/phys-551","sections":[{"days":"R","room":null,"types":["Senior Project"],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":"17:00:00","meetings":[{"days":"R","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"17:00","start_date":"2027-01-20","start_time":"14:30"}],"start_time":"14:30:00","instructors":["Adam C. Lark"]}]},
{"code":"PPOL 101","title":"Introduction to Law","department":"Public Policy","credits":1,"description":"Focus on the American system of law: principally constitutional law, criminal law, and the development of civil rights. Topics include philosophical approaches to justice, English common law, and comparative analysis of French civil law and legal codes in socialist political systems and in majority Muslim countries. Consideration of the challenges to trust in legal institutions from the Supreme Court to local courts and police. Attention also to legal regimes regarding refugees, Native Americans, and defendants with mental illness.","cross_listed":["JLJS 101"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/ppol-public-policy/100/ppol-101","sections":[{"days":"MW","room":null,"types":["Soc, Struct & Inst Hier"],"status":"waitlisted","section":"01","building":null,"capacity":20,"comments":null,"end_time":"15:45:00","meetings":[{"days":"MW","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"15:45","start_date":"2027-01-20","start_time":"14:30"}],"start_time":"14:30:00","instructors":["Ralph J. Eannace"]}]},
{"code":"PPOL 251","title":"Intro Public Policy","department":"Public Policy","credits":1,"description":"The study of policy analysis using and comparing a variety of disciplinary and analytic traditions. Consideration of controversies over particular policies at the national and local level and the premises underlying them. Examination of methods and principles used in formulating and evaluating public policy. Open to seniors with consent of instructor. (American Politics)","cross_listed":["GOVT 251"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/ppol-public-policy/200/ppol-251","sections":[{"days":"TR","room":null,"types":["American Studies","Quantitative & Symbolic R","Soc, Struct & Inst Hier"],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"11:45","start_date":"2027-01-20","start_time":"10:30"}],"start_time":"10:30:00","instructors":["Heather A. Sullivan"]}]},
{"code":"PPOL 273W","title":"Justice Lab Seminar","department":"Public Policy","credits":1,"description":"This seminar forms part of the justice lab program. It focuses on issues of politics and policy. This course forms part of the Justice Lab. Students must apply to be a part of the lab.","cross_listed":["GOVT 273W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/ppol-public-policy/200/ppol-273","sections":[{"days":"MW","room":null,"types":["Co-Lab Course","Jurisprudnc Law Justc Std","Writing Intensive Courses"],"status":"open","section":"01","building":null,"capacity":16,"comments":"Open to Spring 2027 Justice Lab students only.","end_time":"14:15:00","meetings":[{"days":"MW","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Heather A. Sullivan"]}]},
{"code":"PPOL 500","title":"Senior Project","department":"Public Policy","credits":1,"description":"A one semester senior project, culminating in a public policy analysis. This is the capstone course in the Public Policy concentration.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/ppol-public-policy/500/ppol-500","sections":[{"days":"W","room":null,"types":["Senior Project"],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":"16:00:00","meetings":[{"days":"W","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Frank M. Anechiarico"]}]},
{"code":"PSYCH 101","title":"Intro to Psychology","department":"Psychology","credits":1,"description":"An introduction to the science of human behavior. Topics include the nervous system, perception, learning, motivation, cognitive and social development, personality, individual differences, social behavior and psychopathology. In class laboratory exercises to emphasize the use of research methods and data to describe and examine behavior. Some sections may be offered as First-Year Courses.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/psych-psychology/100/psych-101","sections":[{"days":"MWF","room":null,"types":["Qlit Course","Quantitative & Symbolic R"],"status":"open","section":"01","building":null,"capacity":40,"comments":"Not Open to Those Who Took 200-300. Open to Srs., Jrs., Soph., & 1st Yr. Students may only take one full credit 100-level PSYCH course.","end_time":"10:50:00","meetings":[{"days":"MWF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"10:50","start_date":"2027-01-20","start_time":"10:00"}],"start_time":"10:00:00","instructors":["Rachel E. White"]},{"days":"MWF","room":null,"types":["Qlit Course","Quantitative & Symbolic R"],"status":"open","section":"02","building":null,"capacity":40,"comments":"Open to First Years Only. Not Open to Those Who Took 200-300. Students may only take one full credit 100-level PSYCH course.","end_time":"11:50:00","meetings":[{"days":"MWF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"11:50","start_date":"2027-01-20","start_time":"11:00"}],"start_time":"11:00:00","instructors":["Lok-Kin Yeung"]},{"days":"MWF","room":null,"types":["Qlit Course","Quantitative & Symbolic R"],"status":"open","section":"03","building":null,"capacity":40,"comments":"Not Open to Those Who Took 200-300. Students may only take one full credit 100-level PSYCH course.","end_time":"09:50:00","meetings":[{"days":"MWF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"09:50","start_date":"2027-01-20","start_time":"09:00"}],"start_time":"09:00:00","instructors":["Lok-Kin Yeung"]}]},
{"code":"PSYCH 201","title":"Stats & Research Methods","department":"Psychology","credits":1,"description":"The application and interpretation of descriptive and inferential statistics in the study of psychological processes. Some instruction in research design and methodological issues. Students will learn to use the statistical computer program SPSS to analyze data. Topics include the principles of hypothesis testing, t tests, analysis of variance, regression, and some non-parametric statistics. Prerequisites, 101.","cross_listed":["NEURO 201"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/psych-psychology/200/psych-201","sections":[{"days":"MWF","room":null,"types":["Qlit Course","Quantitative & Symbolic R"],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":"10:50:00","meetings":[{"days":"MWF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"10:50","start_date":"2027-01-20","start_time":"10:00"}],"start_time":"10:00:00","instructors":["Siobhan Robinson"]},{"days":"MWF","room":null,"types":["Qlit Course","Quantitative & Symbolic R"],"status":"open","section":"02","building":null,"capacity":40,"comments":null,"end_time":"11:50:00","meetings":[{"days":"MWF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"11:50","start_date":"2027-01-20","start_time":"11:00"}],"start_time":"11:00:00","instructors":["Siobhan Robinson"]}]},
{"code":"PSYCH 204","title":"Human Neuroscience","department":"Psychology","credits":1,"description":"Introduction to the field of neuroscience from a behavioral and cognitive perspective. Survey of experimental and clinical research involving humans and non-human animals, addressing presumed neural mechanisms for cognitive, motivational and emotional states. Analysis of amnesia, aphasia, agnosias, apraxias and disconnection syndromes.","cross_listed":["NEURO 204"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/psych-psychology/200/psych-204","sections":[{"days":"TR","room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":"10:15:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"10:15","start_date":"2027-01-20","start_time":"09:00"}],"start_time":"09:00:00","instructors":["Alexandra List"]},{"days":"TR","room":null,"types":[],"status":"open","section":"02","building":null,"capacity":40,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"11:45","start_date":"2027-01-20","start_time":"10:30"}],"start_time":"10:30:00","instructors":["Alexandra List"]}]},
{"code":"PSYCH 254","title":"Counseling Psychology","department":"Psychology","credits":1,"description":"An overview of the theoretical orientations, treatment approaches and empirical literature in the field of counseling psychology. Examines the mechanisms by which counseling interventions facilitate personal and interpersonal functioning with a focus on emotional, social, educational, vocational and developmental concerns. Does not count toward the Psychology or Neuroscience concentration or the Psychology minor.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/psych-psychology/200/psych-254","sections":[{"days":"W","room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":"10:50:00","meetings":[{"days":"W","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"10:50","start_date":"2027-01-20","start_time":"08:00"}],"start_time":"08:00:00","instructors":["Katherine Warden"]}]},
{"code":"PSYCH 267","title":"Psych Bias Justice System","department":"Psychology","credits":1,"description":"How does group membership (e.g., sex, race, mental health status) shape one's experiences with the criminal justice system? Adopting a chronological approach through an exemplar criminal case (e.g., arrest, arraignment, plea bargaining, trial, sentencing, release), this course will use case law and empirical research to explore the law's continuing efforts - and shortcomings - in addressing and decreasing bias. Does not count toward the Psychology or Neuroscience concentration or the Psychology minor.","cross_listed":["PSYCH 367"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/psych-psychology/200/psych-267","sections":[{"days":"TR","room":null,"types":["Co-Lab Course"],"status":"open","section":"01","building":null,"capacity":40,"comments":"The 200-level of this course is open to Spring 2027 Justice Lab students only.","end_time":"14:15:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Keelah E. Williams"]}]},
{"code":"PSYCH 298","title":"Collaborative Research II","department":"Psychology","credits":0.5,"description":"Collaborative research under the supervision of a faculty member. Focus on data collection and/or analysis. Six to eight hours per week of lab work, plus final oral presentation or research paper. Prerequisites, Permission of the instructor. Student performance will be evaluated as Satisfactory/Unsatisfactory. One-half credit per semester. May be repeated for credit, but does not count toward concentration requirements.","cross_listed":["NEURO 298"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/psych-psychology/200/psych-298","sections":[{"days":null,"room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":[]},{"days":null,"room":null,"types":[],"status":"open","section":"02","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":[]},{"days":null,"room":null,"types":[],"status":"open","section":"03","building":null,"capacity":5,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":[]}]},
{"code":"PSYCH 321W","title":"Psych Gender Leadership","department":"Psychology","credits":1,"description":"Theoretical and methodological examination of how leadership potential is socially constructed, evaluated, and rewarded, and how these processes are shaped by gender stereotypes. Topics include leadership prototypes, role congruity and lack-of-fit models, backlash and bias, intersectionality, and the effects of gender and race on leadership evaluations. Class time is devoted to in-depth analysis of research articles and case studies, along with student-led discussions and presentations. Laboratory component involves two original research projects with data collection, statistical analysis, scholarly writing, and oral presentations. Three hours of class and three hours of laboratory work.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/psych-psychology/300/psych-321","sections":[{"days":"TR","room":null,"types":["Writing Intensive Courses"],"status":"waitlisted","section":"01","building":null,"capacity":18,"comments":null,"end_time":"14:15:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"},{"days":"TR","room":null,"type":"LAB","building":null,"end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"14:30"}],"start_time":"13:00:00","instructors":["Fiona Adjei Boateng"]}]},
{"code":"PSYCH 329","title":"Stress & Psychophysiology","department":"Psychology","credits":1,"description":"A theoretical and methodological exploration of the psychological and physiological mechanisms of stress. Questions will include: How does psychological stress impact health and well-being? What neurobiological mechanisms are involved? What is the role of environmental context? Laboratory exercises will include designing original experiments to examine the role of stress on behavior and physiological activity, as well as analyzing data, writing papers based on findings, and oral and poster presentations. Three hours of class and three hours of laboratory. Does not count toward the lab requirement in Psychology.","cross_listed":["NEURO 329"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/psych-psychology/300/psych-329","sections":[{"days":"TR","room":null,"types":["Quantitative & Symbolic R"],"status":"waitlisted","section":"01","building":null,"capacity":20,"comments":null,"end_time":"10:15:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"10:15","start_date":"2027-01-20","start_time":"09:00"},{"days":"M","room":null,"type":"LAB","building":null,"end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"09:00:00","instructors":["Kelly E. Faig"]}]},
{"code":"PSYCH 330","title":"Systems Neuroscience","department":"Psychology","credits":1,"description":"The primary focus of this course is on the physiological and chemical basis of behavior from a systems perspective. Topics include analysis of sensory and motor systems; motivated behaviors; stress, anxiety and mental illness; and learning and memory. Laboratory exercises introduce students to the anatomy and physiology of the mammalian central nervous system and to some of the principal techniques used in systems and behavioral neuroscience. Three hours of class and three hours of laboratory. Does not count toward the lab requirement in Psychology.","cross_listed":["BIO 330","NEURO 330"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/psych-psychology/300/psych-330","sections":[{"days":"TR","room":null,"types":[],"status":"open","section":"01","building":null,"capacity":10,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"11:45","start_date":"2027-01-20","start_time":"10:30"},{"days":"T","room":"3087","type":"LAB","building":"Taylor Science Center","end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"10:30:00","instructors":["Abigail K. Myers"]},{"days":"TR","room":null,"types":[],"status":"open","section":"02","building":null,"capacity":10,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"11:45","start_date":"2027-01-20","start_time":"10:30"},{"days":"W","room":"3087","type":"LAB","building":"Taylor Science Center","end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"10:30:00","instructors":["Abigail K. Myers"]}]},
{"code":"PSYCH 337","title":"Psychology of Friendship","department":"Psychology","credits":1,"description":"An exploration of theoretical and empirical research on the psychology of friendship, with an emphasis on sociocultural and evolutionary approaches. We will consider questions such as: What is friendship, and what functions does it serve in our lives? How do we seek and maintain friendships? In what ways is friendship similar and different across cultures? Through activities and reflections, students will use course material as a lens for examining their own important relationships.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/psych-psychology/300/psych-306","sections":[{"days":"TR","room":null,"types":[],"status":"waitlisted","section":"01","building":null,"capacity":40,"comments":null,"end_time":"15:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"15:45","start_date":"2027-01-20","start_time":"14:30"}],"start_time":"14:30:00","instructors":["Keelah E. Williams"]}]},
{"code":"PSYCH 353","title":"Adult Psychopathology","department":"Psychology","credits":1,"description":"Introduction to the study of mental disorders in adults, including historical and cultural perspectives. Focus on classification, diagnostic assessment, etiology, treatment, and evaluation of treatment efficacy for the major disorders including anxiety, affective, thought, substance, and eating disorders. Research methods in clinical psychology emphasized. Discussion will include how gender, race, ethnicity, culture, sexuality, and social class relate to our understanding of mental illness and its treatment.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/psych-psychology/300/psych-353","sections":[{"days":"MW","room":null,"types":["Soc, Struct & Inst Hier"],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":"15:45:00","meetings":[{"days":"MW","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"15:45","start_date":"2027-01-20","start_time":"14:30"}],"start_time":"14:30:00","instructors":["Tara L. McKee"]}]},
{"code":"PSYCH 367","title":"Psych Bias Justice System","department":"Psychology","credits":1,"description":"How does group membership (e.g., sex, race, ethnicity, religion) shape one's experiences with the criminal justice system? Adopting a chronological approach through an exemplar criminal case (e.g., arrest, arraignment, plea bargaining, trial, sentencing, release), this course will use case law and empirical research to explore the law's continuing efforts - and shortcomings - in addressing and decreasing bias.","cross_listed":["PSYCH 267"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/psych-psychology/300/psych-367","sections":[{"days":"TR","room":null,"types":["Jurisprudnc Law Justc Std","Soc, Struct & Inst Hier"],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":"14:15:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Keelah E. Williams"]}]},
{"code":"PSYCH 379","title":"Lifespan Development","department":"Psychology","credits":1,"description":"An introduction to the science of lifespan development, from conception and prenatal development to older age and death. Focuses on multiple domains of development, including cognitive, social, physical, and emotional, with emphasis on how development in all domains is shaped by both biological and social/cultural influences (e.g., gender norms, social class, stereotyping and prejudice).","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/psych-psychology/300/psych-379","sections":[{"days":"MW","room":null,"types":["Soc, Struct & Inst Hier"],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":"14:15:00","meetings":[{"days":"MW","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Rachel E. White"]}]},
{"code":"PSYCH 397N","title":"Methods of Evaluation","department":"Psychology","credits":1,"description":"Equips students with skills needed to confirm the clinical efficacy of interventions by subjecting them to experimental evaluation using single-subject designs. Students will learn to develop valid and reliable systems for measuring behavior, to display data using popular and accessible graphing software, and to assess for orderly changes in behavior through visual inspection and interpretation of graphic data. Prerequisites, Psych/Neuro 201 if the course is to count toward the concentration or minor. Open only to participants in the Cooperative Educational Program at the New England Center for Children.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/psych-new-england-center-for-children/300/psych-397n","sections":[{"days":null,"room":null,"types":[],"status":"open","section":"01","building":null,"capacity":5,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":[]}]},
{"code":"PSYCH 398N","title":"Evidence Based Teaching","department":"Psychology","credits":1,"description":"Provides students with a comprehensive review of empirically supported behavioral teaching procedures for individuals with autism and related disabilities. Topics will focus on teaching skills in a variety of content areas such as language, social, and self-help. Procedures for teaching these include, match-to-sample discrimination training, task analysis, as well as prompting procedures including prompt fading and video modeling. Prerequisites, Psych/Neuro 201 if the course is to count toward the concentration or minor. Open only to participants in the Cooperative Educational Program at the New England Center for Children.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/psych-new-england-center-for-children/300/psych-398n","sections":[{"days":null,"room":null,"types":[],"status":"open","section":"01","building":null,"capacity":5,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":[]}]},
{"code":"PSYCH 501","title":"Senior Project","department":"Psychology","credits":1,"description":"Supervised research on a specific problem in psychology. Psych 500 is only offered in the fall semester. Psych 501 is only offered in the spring semester. Students who will finish their degree requirements in December who want to complete a full-year senior project will need to take Psych 500 in the fall three semesters prior to completion and Psych 501 in the spring two semesters prior to completion. Such students will need to consult with the chair of the Psychology Department in the spring semester prior to taking Psych 500 (i.e., four semesters prior to completion of degree requirements) in order to be included in the advisor assignment process. Students who are unable to follow this timeline will be required to complete a one-semester senior project. Open to senior concentrators.","cross_listed":[],"catalog_url":null,"sections":[{"days":null,"room":null,"types":["Senior Project"],"status":"open","section":"01","building":null,"capacity":40,"comments":"Open to Seniors Only.","end_time":null,"meetings":[],"start_time":null,"instructors":["Fiona Adjei Boateng"]},{"days":null,"room":null,"types":["Senior Project"],"status":"open","section":"02","building":null,"capacity":40,"comments":"Open to Seniors Only.","end_time":null,"meetings":[],"start_time":null,"instructors":["Keelah E. Williams"]},{"days":null,"room":null,"types":["Senior Project"],"status":"open","section":"03","building":null,"capacity":40,"comments":"Open to Seniors Only","end_time":null,"meetings":[],"start_time":null,"instructors":["Tara L. McKee"]}]},
{"code":"RELST 108","title":"Bad Religion","department":"Religious Studies","credits":1,"description":"Explore various religious communities and practices that have been considered \"irreligious,\" \"superstitious,\" or \"weird,\" from The Church of Jesus Christ of Latter-day Saints to the Church of Satan. This course does not argue that \"bad religion\" exists, but asks instead how critics and outsiders have located particular religious groups and practices beyond the margins of \"real\" or acceptable religion. Tracking various constructions of \"bad religion\" in America from the 1800s to now, we ask what fears and fantasies of religious \"Others\" can reveal about cultural concerns surrounding gender, race, immigration, and more. In addition to secondary sources, we analyze primary sources, popular culture, and news media as influential sites of religious theorizing, construction, and contestation. (Application)","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/relst-religious-studies/100/relst-108","sections":[{"days":"TR","room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":"Open to Srs., Jrs., Soph., & 1st Yr","end_time":"10:15:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"10:15","start_date":"2027-01-20","start_time":"09:00"}],"start_time":"09:00:00","instructors":["Shelby King"]}]},
{"code":"RELST 111W","title":"Ancient Jewish Wisdom","department":"Religious Studies","credits":1,"description":"An introduction to the Jewish Tradition and Jewish way of reading.","cross_listed":["JWST 111W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/relst-religious-studies/100/relst-111","sections":[{"days":"TR","room":null,"types":["Writing Intensive Courses"],"status":"waitlisted","section":"01","building":null,"capacity":18,"comments":null,"end_time":"15:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"15:45","start_date":"2027-01-20","start_time":"14:30"}],"start_time":"14:30:00","instructors":["Benjamin Steiner"]}]},
{"code":"RELST 131","title":"Religion and Ecology","department":"Religious Studies","credits":1,"description":"This course explores 'Religion and Ecology,' beginning from a North American starting point in the 1960s amidst a budding environmentalist movement. Readings explore how mainly Christian theological communities engaged with a new social movement, before broadening to other religious traditions. The course then proceeds via a new theoretical frame: the religious lives of human communities are located within deep time and geographical space, with an eye to the migration history of the human as a natural kind. Along the way, we responsibly speculate about communities located in (what is now) Africa, the Middle East, Europe, Asia, and the Americas. The course ends by asking: how are we to live into a shared environmental future, and what is the role of our deepest religious commitments? (Application)","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/relst-religious-studies/100/relst-131","sections":[{"days":"WF","room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":"Open to Srs., Jrs., Soph., & 1st Yr","end_time":"14:15:00","meetings":[{"days":"WF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Nan K. Lin"]}]},
{"code":"RELST 143W","title":"Sacred in South Asia","department":"Religious Studies","credits":1,"description":"What constitutes the sacred in south Asia? Is it a person, place, river, hill, temple or nature/ecology? Where and how did the notion of sacrality emerge in South Asia? Is it linked exclusively to religious institutions or is it found in the daily lives of people? This course will examine these questions by exploring the multiple religious traditions of South Asia and examining their essential beliefs, doctrines, institutions, rituals and popular practices through a study of texts, material culture, films and ethnographic accounts.","cross_listed":["ASNST 143W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/relst-religious-studies/100/relst-143","sections":[{"days":"TR","room":null,"types":["Writing Intensive Courses"],"status":"open","section":"01","building":null,"capacity":18,"comments":"Open to 1st Years, Sophomores, & Juniors","end_time":"14:15:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Abhishek S. Amar"]}]},
{"code":"RELST 145","title":"World Films, World Faiths","department":"Religious Studies","credits":1,"description":"Introduces the practices and beliefs of several major world religions (including Judaism, Christianity, Islam, Hinduism and Buddhism) through the medium of film. Exploring Japanese anime, Indonesia documentaries, video films from Ghana, Bollywood mythologicals, Jesus-films from Latin America, Korean-Buddhist films, contemporary fictional glimpses into Jewish life, and more, shows how religious people live and struggle and find joy, by using the audio-visual medium of film. Evening film screenings.","cross_listed":["CNMS 145"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/relst-religious-studies/100/relst-145","sections":[{"days":"MW","room":null,"types":["Cinema and Media Studies"],"status":"open","section":"01","building":null,"capacity":40,"comments":"Open to 1st Yrs, Sophomores, & Juniors","end_time":"09:45:00","meetings":[{"days":"MW","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"09:45","start_date":"2027-01-20","start_time":"08:30"},{"days":"U","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"22:00","start_date":"2027-01-20","start_time":"19:00"}],"start_time":"08:30:00","instructors":["S.B. Rodriguez-Plate"]}]},
{"code":"RELST 146W","title":"Medieval Christianities","department":"Religious Studies","credits":1,"description":"A survey of the development of the Christian religion in premodern Eurasia and the Mediterranean, from its elevation to a state cult in the later Roman Empire to about 1450. Special consideration will be given to the growth of the church and processes of conversion, the problem of authority versus heresy and heterodoxy, and the relationship of the Christian churches to Islam and other non-Christian peoples. Stress on basic skills in the study of history.","cross_listed":["HIST 146W","MDRST 146W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/relst-religious-studies/100/relst-146","sections":[{"days":"MWF","room":null,"types":["Writing Intensive Courses"],"status":"waitlisted","section":"01","building":null,"capacity":18,"comments":"Open to Srs., Jrs., Sophomores, & 1st Yrs","end_time":"11:50:00","meetings":[{"days":"MWF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"11:50","start_date":"2027-01-20","start_time":"11:00"}],"start_time":"11:00:00","instructors":["John T. Eldevik"]}]},
{"code":"RELST 153W","title":"Biographies of the Holy","department":"Religious Studies","credits":1,"description":"This course considers, in a theoretically informed way, some of the issues that arise in thinking about religious ethics comparatively. We focus on exemplars or \"holy\" people: figures who refract the values held to be important by a wider community or society. The course starts by setting up transcendent and immanent frames in the study of religion. We then read biographies of the \"holy,\" pointing out what can be seen through the two frames together. Biographical subjects include exemplary Confucian women from the 1st c. BCE; Buddhist nuns and monks from the 4-6th c. CE; and a 19th-c. biography by Henry David Thoreau of Captain John Brown, read alongside testimonies by Harriet Tubman and W.E.B. Du Bois. (Application)","cross_listed":["SOC 153W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/relst-religious-studies/100/relst-153","sections":[{"days":"TR","room":null,"types":["Writing Intensive Courses"],"status":"open","section":"01","building":null,"capacity":18,"comments":null,"end_time":"14:15:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Nan K. Lin"]}]},
{"code":"RELST 198","title":"Readings in Religious Studies","department":"Religious Studies","credits":0.25,"description":"Religious Studies faculty join with students to read and discuss one important and/or provocative work each semester. May be repeated for credit.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/relst-religious-studies/100/relst-198","sections":[{"days":"W","room":null,"types":[],"status":"open","section":"01","building":null,"capacity":12,"comments":"Open to Srs, Jrs, Soph, & 1st Years","end_time":"12:50:00","meetings":[{"days":"W","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"12:50","start_date":"2027-01-20","start_time":"12:00"}],"start_time":"12:00:00","instructors":["S.B. Rodriguez-Plate"]}]},
{"code":"RELST 207","title":"Social Lives Ancient Dead","department":"Religious Studies","credits":1,"description":"What happened to people after they died in the ancient world? Often, their story was only beginning. This course looks at the ways the dead remained part of everyday life. We will read curse tablets that call on restless spirits, laws about stolen bodies, stories about cities fighting over heroic bones, and Christian accounts of remains that heal or protect the living. We will also study tombs and inscriptions to see how people used the dead to make claims about family, memory, status, and belonging. The course ends close to home. For the final project, students will turn to Hamilton's own cemetery and investigate how one grave, monument, or burial story creates a social life for the dead on our campus. The larger question throughout the course is simple: what can the dead still do for the living? (Application, Interpretation)","cross_listed":["CLASC 207"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/relst-religious-studies/200/relst-207","sections":[{"days":"TR","room":null,"types":[],"status":"waitlisted","section":"01","building":null,"capacity":40,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"11:45","start_date":"2027-01-20","start_time":"10:30"}],"start_time":"10:30:00","instructors":["Sunil Persad"]}]},
{"code":"RELST 210","title":"Minorities in the Middle East","department":"Religious Studies","credits":1,"description":"This course explores how minority communities in the Middle East-Druze, ?Alawites, Kurds, Yezidis, Armenians, Maronites, Copts, Assyrians, and others-have been formed and transformed from the late Ottoman era to the present. Beginning with the shift from imperial pluralism to nation-state \"minorities,\" it examines how religion, identity, nationalism, and political power shape communal identity and minority-state relations. Case studies span Lebanon, Syria, Israel, Turkey, Iran, Iraq, and Egypt, addressing genocide, displacement, nationalism, citizenship, security, and diaspora. Drawing on history, anthropology, religious studies, and political science, students examine how communities negotiate identity, power, and recognition in a plural Middle East. This course examines historical and contemporary experiences of minority communities in the Middle East. Some course materials address difficult subjects, including genocide, mass violence, persecution, forced displacement, sexual violence, religious and ethnic discrimination, and war. These topics are approached in their historical and scholarly contexts and are essential to understanding the experiences of the communities studied in the course. (Location)","cross_listed":["ARABC 210","MEIWS 210"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/relst-religious-studies/200/relst-210","sections":[{"days":"MW","room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":"14:15:00","meetings":[{"days":"MW","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Salman Elamir Amir"]}]},
{"code":"RELST 261","title":"Jewish Feminism","department":"Religious Studies","credits":1,"description":"This course examines the foundational texts, debates, and activism of Jewish feminism in the United States from the early 1970s to the present. Students will explore how Jewish women named and theorized gender inequality in Jewish law, ritual, theology, communal life, and cultural practice-and how those critiques reshaped American Judaism. Readings will situate Jewish feminist thought within wider developments in feminist, religious, and American social history. The course also considers LGBTQ Jewish ideas and activism, asking where they converge with, extend, or challenge Jewish feminist concerns. Students will gain a vocabulary for analyzing the movement's central questions, historical evolution, and enduring impact on Jewish life today.","cross_listed":["JWST 261"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/relst-religious-studies/200/relst-261","sections":[{"days":"TR","room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":"14:15:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Benjamin Steiner"]}]},
{"code":"RELST 263","title":"American Jewish Literature","department":"Religious Studies","credits":1,"description":"What makes a work \"Jewish American literature\"? Must it be written by a Jewish author, center Jewish characters or themes, or appear in a Jewish language? This course uses such questions to explore the American Jewish experience from the earliest Jewish settlement to the present, with particular attention to the period after 1865. Through fiction, poetry, memoir, drama, and other genres, students will examine how writers have represented migration, religion, family, race, belonging, assimilation, and cultural difference. Rather than imposing fixed definitions, the course treats \"Jewish,\" \"American,\" and \"literature\" as contested categories whose meanings have changed over time.","cross_listed":["JWST 263","LIT 263"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/relst-religious-studies/200/relst-263","sections":[{"days":"TR","room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"11:45","start_date":"2027-01-20","start_time":"10:30"}],"start_time":"10:30:00","instructors":["Benjamin Steiner"]}]},
{"code":"RELST 267","title":"Conspiracy Theories & Relig","department":"Religious Studies","credits":1,"description":"Apocalyptic visions, prophecies, and experiences of revelation have mobilized, challenged, and sustained the commitment of religious believers and conspiracy theorists alike. But what else do conspiracy theories and religions share in common, and how do they differ? This course explores intersections of religion and conspiracy theories in American culture from the 19th century to the present day. We examine historical materials alongside contemporary analyses, including millennialist tracts and sermons, conspiracy theory message board websites, illustrations of biblical prophecies, and pictograms of apocalyptic visions. Along the way, we consider how categorizations of \"conspiracy theories\" and \"fringe\" movements have served as critical sites for theorizing and delimiting the margins of \"real\" religion and acceptable belief.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/relst-religious-studies/200/relst-267","sections":[{"days":"TR","room":null,"types":[],"status":"waitlisted","section":"01","building":null,"capacity":40,"comments":"Open to Srs., Jrs., Soph., & 1st Yr","end_time":"15:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"15:45","start_date":"2027-01-20","start_time":"14:30"}],"start_time":"14:30:00","instructors":["Shelby King"]}]},
{"code":"RELST 271","title":"Mother Nature","department":"Religious Studies","credits":1,"description":"How have people in India understood and interacted with mother nature? How do they conceptualize the environment and ecosystems? How do they deal with climate change and ecological disasters? What role does religion play in shaping human attitude to the mother nature? Focusing on Hinduism, Buddhism, and Jainism, the course examines how Indian communities have engaged and negotiated their relationships with the natural world to consider themes including the conception of environment as sacred space, ethical living, non-violence, animal-protection, and food-culture. No prior coursework on Religion or Asia is required.","cross_listed":["ASNST 271"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/relst-religious-studies/200/relst-271","sections":[{"days":"WF","room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":"Open to Srs., Jrs., Soph., & 1st Yr","end_time":"14:15:00","meetings":[{"days":"WF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Corbett Costello"]}]},
{"code":"RELST 291","title":"Imagining Religions","department":"Religious Studies","credits":1,"description":"Students will learn to imagine, analyze, and interpret religion(s) in a wide variety of ways. Students will engage critically with categories of religion, sacred space, the other, colonialism, modernity, globalization, and comparison.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/relst-religious-studies/200/relst-291","sections":[{"days":"T","room":null,"types":["Soc, Struct & Inst Hier"],"status":"open","section":"01","building":null,"capacity":12,"comments":"Open to Seniors, Juniors, & Sophomores","end_time":"16:00:00","meetings":[{"days":"T","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["S.B. Rodriguez-Plate"]}]},
{"code":"RELST 312","title":"Religion and Magic","department":"Religious Studies","credits":1,"description":"Hypnotism. Stage magic. Wonder shows. What do these things have to do with religion? This course explores this question as we trace various intersections of magic and religion from the 18th century to the present day, examining topics including occult and esoteric movements, conjuring practices, mesmerism, hypnotism, spiritualism, telepathy, and stage magic performances. Throughout this course, we engage with critical theories and methods in the study of religion that shed light on the religious dimensions of magic and magical dynamics of religion. In addition to scholarly works from the fields of religious studies and cultural history, we examine a range of cultural data and historical artifacts, from colonial-era trials against alleged sorcerers to 20 th century scientific experiments in psychic phenomena. (Interpretation)","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/relst-religious-studies/300/relst-312","sections":[{"days":"F","room":null,"types":[],"status":"open","section":"01","building":null,"capacity":12,"comments":null,"end_time":"16:00:00","meetings":[{"days":"F","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Shelby King"]}]},
{"code":"RELST 318","title":"How Satan Became the Devil","department":"Religious Studies","credits":1,"description":"Satan does not enter history as the horned ruler of hell we recognize today. This course follows how a relatively minor figure in early Jewish traditions became Christianity's great enemy of God. Along the way, we will meet fallen angels who teach humans forbidden knowledge, demons who possess bodies, monks who claim to wrestle with the Devil in the desert, and exorcists trying to identify what has taken control of a person. We will also see how Satan became connected to heresy, witchcraft, and fears about the end of the world. Rather than treating the Devil as one unchanging character, we will ask why different societies kept reinventing him. Students will explore a larger question: what does a culture reveal about itself when it decides what evil looks like? (Application, Interpretation)","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/relst-religious-studies/300/relst-318","sections":[{"days":"W","room":null,"types":[],"status":"waitlisted","section":"01","building":null,"capacity":12,"comments":null,"end_time":"16:00:00","meetings":[{"days":"W","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Sunil Persad"]}]},
{"code":"RELST 407","title":"US Latino Spiritualities","department":"Religious Studies","credits":1,"description":"Labeled as superstitious or brujas/witches who deal in magic and the occult, Latino practitioners of indigenous and African-diasporic spiritualities are marginalized by US mainstream society and by their own communities. This course examines US Latino authors that reclaim curanderismo, nahualismo/shape-shifting, shamanism and santería to propose alternative modes of knowledge, challenging the Western spiritual-secular divide and Cartesian mind-body dualism that prioritize rational thought. Sixth sense, dream states, trance and holistic medicine are \"other\" ways of knowing. Primary readings by Rudolfo Anaya, Gloria Anzald a, Judith Oritz Cofer. Art and music are studied in African-diasporic ritual. Secondary readings include literary criticism, theoretical and historical texts. Taught in English. Students enrolling in HSPST/LIT/LTAM 407 must complete their senior thesis project in Spanish.","cross_listed":[],"catalog_url":null,"sections":[{"days":null,"room":null,"types":["Proseminar"],"status":"open","section":"01","building":null,"capacity":16,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":[]}]},
{"code":"RSNST 222","title":"Modern Russian History","department":"Russian Studies","credits":1,"description":"An overview of Russian history from the emancipation of the serfs to the collapse of the Soviet Union. Themes of the course include how Russia and the USSR dealt with their sense of \"backwardness\" compared to Europe, the multi-national and multi-religious nature of this vast Eurasian state, and the meanings of \"modernity.\"","cross_listed":["HIST 222"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/rsnst-translation/200/rsnst-222","sections":[{"days":"TR","room":null,"types":["Cultural Diversity Course","Soc, Struct & Inst Hier"],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":"10:15:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"10:15","start_date":"2027-01-20","start_time":"09:00"}],"start_time":"09:00:00","instructors":["Shoshana Keller"]}]},
{"code":"RSNST 227","title":"Lit & Rev:20th & 21st Century","department":"Russian Studies","credits":1,"description":"This course offers a survey of twentieth- and twenty-first-century Russian and Soviet fiction, focusing on the literature that defined this transformative period in Russia's modern history. Taught in English. No knowledge of Russian required.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/rsnst-translation/200/rsnst-227","sections":[{"days":"TR","room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":"15:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"15:45","start_date":"2027-01-20","start_time":"14:30"}],"start_time":"14:30:00","instructors":["Jason A. Cieply"]}]},
{"code":"RSNST 237","title":"Russia and the World","department":"Russian Studies","credits":1,"description":"The course will examine Russia's relations with both its post-Soviet neighbors and the West from the Tsarist era to the present. Topics to be covered include: the formation of the Russian Empire, the Cold War, the evolution of Russian-Western relations since the collapse of communism, Russia's annexation of Crimea in 2014, and the outbreak of a major war with Ukraine in 2022. A central theme of the course will be the evolution of Russian national identity, especially as it relates to Russia's status as an empire and its relationship with the West. (International Relations)","cross_listed":["GOVT 237"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/rsnst-translation/200/rsnst-237","sections":[{"days":"MW","room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":"15:45:00","meetings":[{"days":"MW","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"15:45","start_date":"2027-01-20","start_time":"14:30"}],"start_time":"14:30:00","instructors":["David W. Rivera"]}]},
{"code":"RSNST 262","title":"Siberian Text","department":"Russian Studies","credits":1,"description":"This course is an exploration of five centuries of writing in and about Siberia. While we will root ourselves in the socio-historical context, our main goal is to engage meaningfully with the very process of the formation of the Siberian Text. By this, scholars of the region mean the body of works that emerged out of the geographical, political, anthropological, and cultural categorizations of Siberia. The plurality of voices and the diversity of spatial experiences engaged in the process of creating the Siberian Text include travelers, criminals, political prisoners, religious dissenters, shamans, hunters, ethnographers, missionaries, vagabonds, and peasants. Probing the fraught legacy of the current spatial discourse on Siberia, the course will examine a variety of media and genres, including official documents, travelogues, oral tradition(s), works of fiction, autobiographies, pictorial art, and film. In addition to the transnational and transhistorical dimensions, we will engage with theories of space and place, imagined geographies, and ecocriticism.","cross_listed":["AIIS 262","LIT 262"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/rsnst-translation/200/rsnst-262","sections":[{"days":"MW","room":null,"types":["Soc, Struct & Inst Hier"],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":"14:15:00","meetings":[{"days":"MW","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Ani Abrahamyan"]}]},
{"code":"RSNST 550","title":"Senior Seminar","department":"Russian Studies","credits":1,"description":"Independent work consisting of the preparation and presentation of a research paper, translation or other project designed by the student. Requires research using Russian-language sources. Open to senior concentrators only.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/rsnst-translation/500/rsnst-550","sections":[{"days":null,"room":null,"types":["Cultural Diversity Course","Senior Project"],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Sharon W. Rivera"]}]},
{"code":"RUSSN 120","title":"Second Term Russian","department":"Russian","credits":1,"description":"Continued development of skills in spoken and written Russian. Intensive use of audio/visual and computer materials. Prerequisites, 110 or equivalent.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/russn-russian-language/100/russn-120","sections":[{"days":"MWF","room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":"11:50:00","meetings":[{"days":"MWF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"11:50","start_date":"2027-01-20","start_time":"11:00"}],"start_time":"11:00:00","instructors":["Jason A. Cieply"]}]},
{"code":"RUSSN 220","title":"Fourth Term Russian","department":"Russian","credits":1,"description":"Continuation of third-term Russian. Introduction to the language of popular culture, including contemporary film and music.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/russn-russian-language/200/russn-220","sections":[{"days":"MWF","room":null,"types":["Cultural Diversity Course"],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":"11:50:00","meetings":[{"days":"MWF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"11:50","start_date":"2027-01-20","start_time":"11:00"}],"start_time":"11:00:00","instructors":["Ani Abrahamyan"]}]},
{"code":"RUSSN 298","title":"Adv Language & Culture","department":"Russian","credits":0.25,"description":"1/4-credit class that must be taken in conjunction with a course in English. Additional weekly session to analyze and discuss the material in the original language. May be repeated for credit.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/russn-russian-language/200/russn-298","sections":[{"days":null,"room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Ani Abrahamyan"]}]},
{"code":"RUSSN 380","title":"Advanced Russian II","department":"Russian","credits":1,"description":"Continuation of Russian Studies 370. The focus of this class will be on writing, reading, and talking about daily life, or \"byt\" in diary form, broadly conceived. Works of literature and culture will be compared with social media posts in both long (blog posts) and short formats (memes, tweets, tik toks, etc). Advanced readings and discussion will be accompanied by a thorough review of grammar and difficult grammar points.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/russn-russian-language/300/russn-380","sections":[{"days":"MW","room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":"14:15:00","meetings":[{"days":"MW","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Jason A. Cieply"]}]},
{"code":"SOC 101","title":"Introductory Sociology","department":"Sociology","credits":1,"description":"Sociological perspective on human behavior. Classic and contemporary sociological concepts that further an understanding of the structure, process, stability and change of social life. Not open to students who have taken SOC 110 or SOC 126.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/soc-sociology/100/soc-101","sections":[{"days":"MW","room":null,"types":["Soc, Struct & Inst Hier"],"status":"open","section":"01","building":null,"capacity":40,"comments":"Open to 1st Yrs and Sophomores Only Not Open to Those Who Took Soc 110","end_time":"09:45:00","meetings":[{"days":"MW","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"09:45","start_date":"2027-01-20","start_time":"08:30"}],"start_time":"08:30:00","instructors":["Timothy Sacco"]}]},
{"code":"SOC 126","title":"Soc Health & Illness","department":"Sociology","credits":1,"description":"This course will give students an introduction to the sociological study of health and illness. While sociologists have taken the study of medicine seriously since at least the 1950s, health and illness are phenomena whose relationship to human society and experience are long and complex. In order to explore this reality, this class will draw on the empirical work of historians, anthropologists, sociologists, and even fiction writers to explore the personal and social elements of sickness and health.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/soc-sociology/100/soc-126","sections":[{"days":"WF","room":null,"types":[],"status":"waitlisted","section":"01","building":null,"capacity":40,"comments":null,"end_time":"14:15:00","meetings":[{"days":"WF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Matthew K. Grace"]}]},
{"code":"SOC 153W","title":"Biographies of the Holy","department":"Sociology","credits":1,"description":"This course considers, in a theoretically informed way, some of the issues that arise in thinking about religious ethics comparatively. We focus on exemplars or \"holy\" people: figures who refract the values held to be important by a wider community or society. The course starts by setting up transcendent and immanent frames in the study of religion. We then read biographies of the \"holy,\" pointing out what can be seen through the two frames together. Biographical subjects include exemplary Confucian women from the 1st c. BCE; Buddhist nuns and monks from the 4-6th c. CE; and a 19th-c. biography by Henry David Thoreau of Captain John Brown, read alongside testimonies by Harriet Tubman and W.E.B. Du Bois. (Application)","cross_listed":["RELST 153W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/soc-sociology/100/soc-153","sections":[{"days":"TR","room":null,"types":["Writing Intensive Courses"],"status":"open","section":"01","building":null,"capacity":18,"comments":null,"end_time":"14:15:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Nan K. Lin"]}]},
{"code":"SOC 212","title":"Sociology of Elites","department":"Sociology","credits":1,"description":"Who rules-and how do they stay on top? This course examines inequality from above, exploring how elites are formed, legitimated, and challenged across diverse settings. Case studies range from Ivy League admissions and Wall Street hiring to technology elites, Russian oligarchs, emergent Chinese elites, Indian caste hierarchies, and royal families in the Gulf. We will explore how class, race, and gender shape the formation of elite groups, their capacity to appropriate resources, and their struggles with rival elites over power and resources. By the end of the course, students will have the analytical tools to understand not just who holds power, but how that power is reproduced, justified, and contested.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/soc-sociology/200/soc-212","sections":[{"days":"TR","room":null,"types":["Soc, Struct & Inst Hier"],"status":"waitlisted","section":"01","building":null,"capacity":40,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"11:45","start_date":"2027-01-20","start_time":"10:30"}],"start_time":"10:30:00","instructors":["Harun Ercan"]}]},
{"code":"SOC 217","title":"Sociology of Education","department":"Sociology","credits":1,"description":"This course provides a sociological lens for analyzing education and educational inequality in the United States. Over the course of the semester, we will use various theories to explore education as a social institution, going beyond our own individual experiences and personal ideologies. In addition to covering the foundational ideas in the sociology of education, we will spend considerable time exploring the myriad ways that education impacts, and is impacted by, broader patterns of inequality. We will also use empirical studies to examine external factors that affect student experiences and shape learning outcomes; factors such as the role of families, neighborhoods, and schools, themselves. Salient topics include racial segregation, economic stratification within and between schools, technology, tracking, teacher pedagogy, immigration, English Language Learners, punishment, higher education, and the future of education in a demographically and culturally diversifying society.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/soc-sociology/200/soc-217","sections":[{"days":"TR","room":null,"types":["Soc, Struct & Inst Hier"],"status":"waitlisted","section":"01","building":null,"capacity":40,"comments":null,"end_time":"10:15:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"10:15","start_date":"2027-01-20","start_time":"09:00"}],"start_time":"09:00:00","instructors":["Mahala D. Stewart"]}]},
{"code":"SOC 224","title":"Crime, Law, and Inequality","department":"Sociology","credits":1,"description":"This course examines crime, criminalization, and social control from a sociological perspective. Rather than treating crime as simply the violation of law, we examine how crime is socially and politically constructed and how practices of punishment and regulation emerge through broader struggles over power, morality, and social order. Topics include moral panics, addiction and criminalization, policing and surveillance, mass incarceration, organized crime, mafia networks, illicit drug economies, corporate crime, state violence, terrorism, and border enforcement. Students will critically evaluate competing explanations of crime and examine how criminalization and social control both shape and are shaped by relations of power, inequality, governance, and social change.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/soc-sociology/200/soc-224","sections":[{"days":"TR","room":null,"types":["Soc, Struct & Inst Hier"],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":"15:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"15:45","start_date":"2027-01-20","start_time":"14:30"}],"start_time":"14:30:00","instructors":["Harun Ercan"]}]},
{"code":"SOC 228","title":"Work, Organizations & Inequal","department":"Sociology","credits":1,"description":"This course will examine how complex organizations structure work in the United States, how work has changed, and why. We will examine the structure of work from an organizational perspective, which introduces students to a framework for thinking about how social institutions (such as federal policies or racial inequality) shape the experiences of the everyday people. Students will begin to deepen their knowledge about the structure of work in the U.S., why it looks the way that it does today, and who benefits (or does not benefit) from this system.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/soc-sociology/200/soc-228","sections":[{"days":"MW","room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":"14:15:00","meetings":[{"days":"MW","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Timothy Sacco"]}]},
{"code":"SOC 256","title":"Sociology of Immigration","department":"Sociology","credits":1,"description":"This course examines international migration as a social process, with a main focus on immigration to the United States. It provides sociological perspectives to understand why immigration happens, how it occurs, and what consequences and outcomes it produces. We will explore theories of migration and compare and contrast trends in old world and new world migration systems, as well as the American migration experience. Prerequisites, One course in sociology or consent of instructor.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/soc-sociology/200/soc-256","sections":[{"days":"TR","room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":"15:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"15:45","start_date":"2027-01-20","start_time":"14:30"}],"start_time":"14:30:00","instructors":["Janina L. Selzer"]}]},
{"code":"SOC 276W","title":"Global Commemoration","department":"Sociology","credits":1,"description":"This course examines how atrocities - big and small - are remembered around the globe: What is the process through which individual experiences are transformed into credible testimonies and collective traumas? What role do state actors, educational institutions, community organizations, and civic society play in the production of memory? And what is the purpose of keeping the past alive if societies are ever-changing and evolving? We will trace the long-lasting legacies of human brutality to different parts of the globe. By listening to survivors, exploring different forms of testimonies, and combing through evidence accumulated by investigative journalists, we will critically engage with and expand upon foundational sociological texts on history, memory, and commemoration.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/soc-sociology/200/soc-276","sections":[{"days":"TR","room":null,"types":[],"status":"open","section":"01","building":null,"capacity":18,"comments":null,"end_time":"14:15:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Janina L. Selzer"]}]},
{"code":"SOC 301W","title":"Sociological Theory","department":"Sociology","credits":1,"description":"Examination of classic and contemporary sociological concepts and perspectives. The theorists covered include Marx, Weber, Durkheim, Freud, Mead, Berger and Luckmann, and Foucault. Prerequisites, two sociology courses.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/soc-sociology/300/soc-301","sections":[{"days":"TR","room":null,"types":["Soc, Struct & Inst Hier","Writing Intensive Courses"],"status":"open","section":"01","building":null,"capacity":18,"comments":null,"end_time":"10:15:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"10:15","start_date":"2027-01-20","start_time":"09:00"}],"start_time":"09:00:00","instructors":["Stephen J. Ellingson"]}]},
{"code":"SOC 305","title":"Urban America","department":"Sociology","credits":1,"description":"Although globalization scholars at the turn of the millennium predicted the loss of importance of the local, cities have continued to be vital anchors of social, economic, political, and cultural life. While they may serve as a safe haven for some, they are simultaneously the site of continuous political struggles over the boundaries of belonging. Tracing the history of urbanization in the U.S., this course explores various facets of contemporary urban life, including urban disempowerment, poverty, segregation, and gentrification. At the same time, we will look at the many ways in which residents - including migrants and members of the LGBTQIA+ community - claim their right to the city.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/soc-sociology/300/soc-305","sections":[{"days":"W","room":null,"types":[],"status":"open","section":"01","building":null,"capacity":12,"comments":null,"end_time":"16:00:00","meetings":[{"days":"W","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Janina L. Selzer"]}]},
{"code":"SOC 315","title":"Sociology of Violence","department":"Sociology","credits":1,"description":"Violence is deeply intertwined with power, inequality, and struggles among social groups, political movements, and the state. It ranges from direct physical harm to structural and symbolic forms that often go unrecognized as violence at all. This course traces how power inequalities enable violence and its erasure, and how state and nonstate violence interact to reproduce or reshape those inequalities. Using a comparative global approach, we examine specific sites and collective contentious events where these dynamics become visible, from prisons and borders to war and militarized conflict, genocide, torture, counterinsurgency, terrorism, and counterrevolution.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/soc-sociology/300/soc-315","sections":[{"days":"F","room":null,"types":[],"status":"open","section":"01","building":null,"capacity":12,"comments":null,"end_time":"16:00:00","meetings":[{"days":"F","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Harun Ercan"]}]},
{"code":"SOC 325","title":"Medicine in America","department":"Sociology","credits":1,"description":"We take for granted medicine as we know it today, yet at the turn of the 20th century, medical practice could have taken any number of directions. Why did allopathic medicine win out over its competitors to consolidate professional and cultural authority over health? How has the patient-provider relationship evolved from an asymmetric model to one characterized by patient consumerism? How do trainees learn medicine's \"hidden curriculum\"? Looking forward, how will providers fare against challenges to autonomy posed by insurance companies, for-profit hospitals, politicians, and AI? To answer these and related questions, this course draws on empirical studies, historical accounts, and media to examine how the profession of medicine has been constructed, contested, and transformed over time.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/soc-sociology/300/soc-325","sections":[{"days":"WF","room":null,"types":[],"status":"open","section":"01","building":null,"capacity":12,"comments":null,"end_time":"15:45:00","meetings":[{"days":"WF","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"15:45","start_date":"2027-01-20","start_time":"14:30"}],"start_time":"14:30:00","instructors":["Matthew K. Grace"]}]},
{"code":"SOC 329","title":"Sem Soc Production Food","department":"Sociology","credits":1,"description":"Examines the production and consumption of food in contemporary societies from a sociological perspective. We will study how food shapes personal identity and communal life; the organizational and institutional contexts food production from farm to table; the role food plays in popular culture and the rise of alternative food movements. Covers such topics as food, communal identity and family; the culture and practices of \"Foodies\"; the world of the restaurant kitchen; globalization and changes in farming and food consumption. Prerequisites, one sociology course.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/soc-sociology/300/soc-329","sections":[{"days":"TR","room":null,"types":["Soc, Struct & Inst Hier"],"status":"open","section":"01","building":null,"capacity":12,"comments":"Open to Srs., Jrs., and Sophomores","end_time":"14:15:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Stephen J. Ellingson"]}]},
{"code":"SOC 342","title":"Sociology of Climate Action","department":"Sociology","credits":1,"description":"In the face of the ongoing climate crisis, we are also witnessing deployment of climate solutions: electrification of transportation, renewable energy development, reforestation initiatives, and reductions in animal agriculture. How do communities react to these approaches to climate action? We unpack theoretical and on-the-ground perspectives on what climate change means among different groups of people and explore people's social location influences how they understand and respond to it individually and collectively. We examine how colonialism, and macroeconomic structures shape perspectives on the experience of the climate crisis and responses to it. Students apply their theoretical understanding in structured community conversations about climate solutions with community stakeholders.","cross_listed":["ENVST 342"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/soc-sociology/300/soc-342","sections":[{"days":"T","room":null,"types":["Experiential Learning"],"status":"waitlisted","section":"01","building":null,"capacity":20,"comments":null,"end_time":"16:00:00","meetings":[{"days":"T","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Aaron L. Strong","Jaime L. Kucinskas"]}]},
{"code":"SOC 351","title":"AI and Society","department":"Sociology","credits":1,"description":"Artificial Intelligence (AI) will shape society in profound ways, disrupting fields like higher education, government, science, or medicine. Yet integrating AI responsibly into society remains difficult. This course explores the sociological dimensions of AI, from its historical roots to today's debates around bias, autonomy, and changing human relationships. Students will critically examine how AI systems perceive, reason, and communicate, with emphasis on machine learning's role in driving AI capabilities. The course also unpacks the politics of algorithms, data, and code, and how AI is socially shaped in practice. Drawing on social science research on technology, work, media, and inequalities, students will investigate how AI can be developed and deployed in ways that align with human values and create meaningful social impact.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/soc-sociology/300/soc-351","sections":[{"days":"T","room":null,"types":[],"status":"open","section":"01","building":null,"capacity":12,"comments":null,"end_time":"16:00:00","meetings":[{"days":"T","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Timothy Sacco"]}]},
{"code":"SOC 550","title":"Senior Project","department":"Sociology","credits":1,"description":"Investigation, through original research, of a sociological topic resulting in a thesis. Open to seniors only.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/soc-sociology/500/soc-550","sections":[{"days":null,"room":null,"types":["Senior Project"],"status":"open","section":"01","building":null,"capacity":40,"comments":"Restricted to Sr. SOC majors only","end_time":null,"meetings":[],"start_time":null,"instructors":["Stephen J. Ellingson"]},{"days":null,"room":null,"types":["Senior Project"],"status":"open","section":"02","building":null,"capacity":40,"comments":"Restricted to Sr. SOC majors only","end_time":null,"meetings":[],"start_time":null,"instructors":["Mahala D. Stewart"]}]},
{"code":"THETR 100","title":"Intro to Making Thetr","department":"Theatre","credits":1,"description":"This is the gateway course for all theatre courses. This class combines the study of theatre and drama as it reflects, represents and interprets diverse cultures with a hands-on examination of how theatre is made. Through readings, lectures, discussions and projects the class will explore the ideas, strategies and languages of theatre (acting, directing, playwriting, designing) that theatre artists use to create contemporary theatrical performance.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/thetr-theatre/100/thetr-100","sections":[{"days":"TR","room":"219","types":["Soc, Struct & Inst Hier","Speaking Intensive Course"],"status":"waitlisted","section":"01","building":"Kennedy Center Theatre/Arts","capacity":20,"comments":"Open to Srs., Jrs., Soph., & 1st Yrs.","end_time":"14:15:00","meetings":[{"days":"TR","room":"219","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"},{"days":"TR","room":"218","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Emily K. Harrison"]}]},
{"code":"THETR 102","title":"Acting Styles: Realism","department":"Theatre","credits":1,"description":"This course builds upon the ideas and techniques of modern realism and its American adaptations through the works of Uta Hagen and Robert Cohen. Students will gain a foundation in an acting process that includes body and voice awareness and use, sense memory, substitution, emotional memory and character actions as well as scene study.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/thetr-theatre/100/thetr-102","sections":[{"days":"MW","room":"218","types":["Soc, Struct & Inst Hier","Speaking Intensive Course"],"status":"waitlisted","section":"01","building":"Kennedy Center Theatre/Arts","capacity":16,"comments":null,"end_time":"14:15:00","meetings":[{"days":"MW","room":"218","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"},{"days":"MW","room":"219","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Mark M. Cryer"]}]},
{"code":"THETR 142","title":"Production","department":"Theatre","credits":0.5,"description":"The study of theatre through participation (performance, management and/or technical work) in a faculty-directed production. Students must pre-register for this class; for 141F first-year students may register during orientation. Preregistration does not guarantee an acting role. Auditions will take place at the start of the semester, and students not acting will perform a technical/production role. One-half credit. May be repeated for credit.","cross_listed":[],"catalog_url":null,"sections":[{"days":"MTWRF","room":"211","types":["Soc, Struct & Inst Hier","Speaking Intensive Course"],"status":"open","section":"01","building":"Kennedy Center Theatre/Arts","capacity":40,"comments":"Instructor's Signature Req.","end_time":"19:00:00","meetings":[{"days":"MTWRF","room":"211","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2027-05-11","end_time":"19:00","start_date":"2027-01-20","start_time":"16:15"},{"days":"MTWRF","room":"217","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2027-05-11","end_time":"19:00","start_date":"2027-01-20","start_time":"16:15"},{"days":"MTWRF","room":"219","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2027-05-11","end_time":"19:00","start_date":"2027-01-20","start_time":"16:15"}],"start_time":"16:15:00","instructors":["Jess Buttery","Emily K. Harrison","Tobin R. Ost"]}]},
{"code":"THETR 208","title":"Stage Combat","department":"Theatre","credits":1,"description":"This is a class on stage combat, armed and unarmed. How to safely fight on stage and make it look real.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/thetr-theatre/200/thetr-208","sections":[{"days":"F","room":"217","types":["Proseminar"],"status":"waitlisted","section":"01","building":"Kennedy Center Theatre/Arts","capacity":16,"comments":"Open to Srs., Jrs., Soph., & 1st Yr","end_time":"16:00:00","meetings":[{"days":"F","room":"217","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"13:00"},{"days":"F","room":"218","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["James S. Drake"]}]},
{"code":"THETR 213","title":"Lighting Design","department":"Theatre","credits":1,"description":"An in-depth exploration of lighting and projection design for live performance. The course will cover the process, techniques, equipment and methodologies of these theatre design disciplines. These include; composition, color theory, projection mapping, CAD drafting, as well as lighting for the camera.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/thetr-theatre/200/thetr-213","sections":[{"days":"TR","room":"217","types":["Quantitative & Symbolic R"],"status":"open","section":"01","building":"Kennedy Center Theatre/Arts","capacity":12,"comments":"Open to Srs., Jrs., Soph., & 1st Yr","end_time":"11:45:00","meetings":[{"days":"TR","room":"217","type":"STU","building":"Kennedy Center Theatre/Arts","end_date":"2027-05-11","end_time":"11:45","start_date":"2027-01-20","start_time":"10:30"}],"start_time":"10:30:00","instructors":["Jess Buttery"]}]},
{"code":"THETR 215","title":"Scene Painting","department":"Theatre","credits":1,"description":"Through a series of projects and demonstrations, introduces students to the basic principles ofscenic painting for film, television and the performing arts. Topics covered will include color mixing, texture, faux finishing (wood grain, marble, etc.), brush and spray techniques, trompe-l'oeil, and large scale cartooning and painting.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/thetr-theatre/200/thetr-215","sections":[{"days":"F","room":"217","types":[],"status":"open","section":"01","building":"Kennedy Center Theatre/Arts","capacity":12,"comments":"Open to Seniors, Juniors, and Sophomores","end_time":"12:00:00","meetings":[{"days":"F","room":"217","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2027-05-11","end_time":"12:00","start_date":"2027-01-20","start_time":"09:00"}],"start_time":"09:00:00","instructors":["Tobin R. Ost"]}]},
{"code":"THETR 217","title":"Stage Management","department":"Theatre","credits":1,"description":"Through this course students will learn the principles of stage management for theatrical productions. How to facilitate the needs of the production through each of its stages, create industry-standard procedures, paperwork, develop good communication/organizational skills as well as an appreciation of the tact/details that stage managers bring to each production.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/thetr-theatre/200/thetr-217","sections":[{"days":"M","room":"220","types":[],"status":"open","section":"01","building":"Kennedy Center Theatre/Arts","capacity":12,"comments":"Open to Srs., Jrs., Soph., & 1st Yr","end_time":"22:00:00","meetings":[{"days":"M","room":"220","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2027-05-11","end_time":"22:00","start_date":"2027-01-20","start_time":"19:00"}],"start_time":"19:00:00","instructors":["Margot Vangel"]}]},
{"code":"THETR 231","title":"Intermed Media: New Frontiers","department":"Theatre","credits":1,"description":"This class will survey and create emergent and non -linear forms of storytelling using digital and hybrid tools. We will examine notions of narrative authority and hybridity in a digital age and think through different ways we might use technology to distill, break apart or reify modes of communication and visual metaphor. Discussion will push boundaries of traditional storytelling and consider connectivity, liveness and embodied presence. This course will draw on multiple forms of expression including but not limited to digital media, performance, sound, XR, web and network environments.","cross_listed":["DARTS 231","MUSIC 231"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/thetr-theatre/200/thetr-231","sections":[{"days":"R","room":"143","types":[],"status":"open","section":"01","building":"Kennedy Center Theatre/Arts","capacity":16,"comments":null,"end_time":"16:00:00","meetings":[{"days":"R","room":"143","type":"STU","building":"Kennedy Center Theatre/Arts","end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"13:00"},{"days":"R","room":"124","type":"STU","building":"Kennedy Center Theatre/Arts","end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Anna Huff"]}]},
{"code":"THETR 302","title":"Adv Acting:shakespeare","department":"Theatre","credits":1,"description":"Classical texts and contemporary performance. Focus on Shakespeare, language and character. May include other classical dramatists Scene and monologue work, textual analysis, vocal and speaking preparedness, verse and heightened speech, characterization, improvisation and rehearsals.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/thetr-theatre/300/thetr-302","sections":[{"days":"MW","room":"217","types":["Speaking Intensive Course"],"status":"open","section":"01","building":"Kennedy Center Theatre/Arts","capacity":16,"comments":null,"end_time":"11:45:00","meetings":[{"days":"MW","room":"217","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2027-05-11","end_time":"11:45","start_date":"2027-01-20","start_time":"10:30"},{"days":"MW","room":"218","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2027-05-11","end_time":"11:45","start_date":"2027-01-20","start_time":"10:30"},{"days":"MW","room":"219","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2027-05-11","end_time":"11:45","start_date":"2027-01-20","start_time":"10:30"}],"start_time":"10:30:00","instructors":["Mark M. Cryer"]}]},
{"code":"THETR 550","title":"Senior Thesis","department":"Theatre","credits":1,"description":"A project resulting in either a research paper or the composition of a play. Open to senior concentrators only.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/thetr-theatre/500/thetr-550","sections":[{"days":null,"room":null,"types":["Senior Project"],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Mark M. Cryer"]}]},
{"code":"THETR 560","title":"Senior Perf.&productn","department":"Theatre","credits":1,"description":"An acting showcase, the directing of a play, costume, set and/or lighting design for a departmental production. Substantial written component comprising research into the historical, theoretical and socio-cultural contexts of the chosen work. Following submission of the monograph and completion of production, each student will participate in the evaluation of her/his project with an evaluating committee. Open to senior concentrators only. Senior project proposals, written in consultation with faculty, are due at the end of the fall semester of the senior year.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/thetr-theatre/500/thetr-560","sections":[{"days":null,"room":null,"types":["Senior Project"],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Mark M. Cryer"]}]},
{"code":"WMGST 101","title":"Intro Women&gender Studies","department":"Women's and Gender Studies","credits":1,"description":"An interdisciplinary investigation of past and present views of women and their roles, treatment and experiences in institutions such as the family, the state, the work force, language and sexuality. The diversity of women's experiences across age, class, ethnic, sexual, racial and national lines introduced, and theories of feminism and of women's studies discussed.\n\nMay be offered as a standard course or FYC as well as writing intensive, non-writing intensive, or speaking intensive at the discretion of the department. Please check the schedule for details.","cross_listed":["WMGST 101W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/wmgst-womens-and-gender-studies/100/wmgst-101","sections":[{"days":"TR","room":null,"types":["Cultural Diversity Course","Diversity Course","Soc, Struct & Inst Hier","Speaking Intensive Course"],"status":"open","section":"01","building":null,"capacity":20,"comments":"Open to 1st Yrs, Soph. & Jrs. Only. This section is Speaking Intensive.","end_time":"10:15:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"10:15","start_date":"2027-01-20","start_time":"09:00"}],"start_time":"09:00:00","instructors":["Taveeshi Singh"]}]},
{"code":"WMGST 101W","title":"Intro Women&gender Studies","department":"Women's and Gender Studies","credits":1,"description":"An interdisciplinary investigation of past and present views of women and their roles, treatment and experiences in institutions such as the family, the state, the work force, language and sexuality. The diversity of women's experiences across age, class, ethnic, sexual, racial and national lines introduced, and theories of feminism and of women's studies discussed.\n\nMay be offered as a standard course or FYC as well as writing intensive, non-writing intensive, or speaking intensive at the discretion of the department. Please check the schedule for details.","cross_listed":["WMGST 101"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/wmgst-womens-and-gender-studies/100/wmgst-101","sections":[{"days":"TR","room":null,"types":["Cultural Diversity Course","Diversity Course","Proseminar","Soc, Struct & Inst Hier","Writing Intensive Courses"],"status":"waitlisted","section":"01","building":null,"capacity":18,"comments":"Open to 1st Yrs, Soph. & Jrs. Only","end_time":"11:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"11:45","start_date":"2027-01-20","start_time":"10:30"}],"start_time":"10:30:00","instructors":["Margaret Gentry"]},{"days":"MW","room":null,"types":["Cultural Diversity Course","Diversity Course","Proseminar","Soc, Struct & Inst Hier","Writing Intensive Courses"],"status":"waitlisted","section":"02","building":null,"capacity":18,"comments":"Open to 1st Yrs, Soph. & Jrs. Only","end_time":"14:15:00","meetings":[{"days":"MW","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Jessina Emmert"]},{"days":"TR","room":null,"types":["Cultural Diversity Course","Diversity Course","Proseminar","Soc, Struct & Inst Hier","Writing Intensive Courses"],"status":"waitlisted","section":"03","building":null,"capacity":18,"comments":"Open to 1st Yrs, Soph. & Jrs. Only","end_time":"15:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"15:45","start_date":"2027-01-20","start_time":"14:30"}],"start_time":"14:30:00","instructors":["Amy Marvin"]}]},
{"code":"WMGST 146W","title":"Black Women's Lit Renaissance","department":"Women's and Gender Studies","credits":1,"description":"The twenty-year period between 1970 and 1990 is often referred to as the \"Black Women's Literary Renaissance\" due to the unprecedented amount of literary and cultural production from black women in the United States. This course explores its profound contributions to black life and literature. Students will examine the intersections and oppositions among political movements, such as the Lesbian Feminist Movement and the Black Power Movement, and identify how these connections shaped the aesthetic landscape of the time. Course materials will include essays, novels, poems, and visual art, featuring Alice Walker, Toni Cade Bambara, bell hooks, Lorna Simpson, and others.","cross_listed":["AFRST 146W","LIT 146W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/wmgst-womens-and-gender-studies/100/wmgst-146","sections":[{"days":"MW","room":null,"types":["Writing Intensive Courses"],"status":"waitlisted","section":"01","building":null,"capacity":18,"comments":"Open to First Years and Sophomores only.","end_time":"09:45:00","meetings":[{"days":"MW","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"09:45","start_date":"2027-01-20","start_time":"08:30"}],"start_time":"08:30:00","instructors":["Tara M. Holman"]}]},
{"code":"WMGST 201W","title":"Intro Feminist Thought","department":"Women's and Gender Studies","credits":1,"description":"An interdisciplinary examination of the history and contemporary practice of feminist thought. Topics include the history of feminist thought in Western culture, the broadening and complication of that canon to include examinations of race, class, gender, sexuality, ableism and ageism, and the implications of global feminist thought. (Political Theory)","cross_listed":["GOVT 201W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/wmgst-womens-and-gender-studies/200/wmgst-201","sections":[{"days":"TR","room":null,"types":["Cultural Diversity Course","Diversity Course","Writing Intensive Courses"],"status":"open","section":"01","building":null,"capacity":18,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"11:45","start_date":"2027-01-20","start_time":"10:30"}],"start_time":"10:30:00","instructors":["Amy Marvin"]}]},
{"code":"WMGST 203","title":"Women and War","department":"Women's and Gender Studies","credits":1,"description":"This course examines the ways war and processes of militarization impact women in the Global North and the Global South. Discussion will be accompanied by an analysis of categories such as \"women,\" \"gender\" and \"sexuality\" in relation to the \"state\" and \"nation\" during periods of warfare and armed conflict. We will engage with a range of interdisciplinary texts on gender and militarism. These narratives will be grounded by theoretical readings that explore the ongoing debates and tensions among feminists regarding nationalism, violence, war and militarization.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/wmgst-womens-and-gender-studies/200/wmgst-203","sections":[{"days":"TR","room":null,"types":["Diversity Course"],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":"14:15:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"14:15","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Taveeshi Singh"]}]},
{"code":"WMGST 217","title":"Intro U.S. Latinx/Lit","department":"Women's and Gender Studies","credits":1,"description":"Examines cultural production of representative U.S. Latinx writers primarily from the civil rights movement to present. The course explores Latinx writers' engagement with language, political status, race, gender, nationality, and generational markers to reveal both the fluidity and instability of the Latinx imaginary. Readings include autobiographical and biographical works, bildungsroman, memoir, historical novel and vignettes in an exploration of the self and one's relation to collective identity. Taught in English. Not open to seniors.","cross_listed":["HSPST 217","LIT 217","LTAM 217"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/hspst-hispanic-studies/200/hspst-217","sections":[{"days":"TR","room":null,"types":["Proseminar"],"status":"open","section":"01","building":null,"capacity":20,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"11:45","start_date":"2027-01-20","start_time":"10:30"}],"start_time":"10:30:00","instructors":["Marissa L. Ambio"]}]},
{"code":"WMGST 224W","title":"Gender,space,identity","department":"Women's and Gender Studies","credits":1,"description":"This course examines how racialized and gendered identities are made in relation to space. How does gender intersect with race, class and other power relations embedded in the places we live? How do women and men come to occupy different places in the world literally and figuratively or occupy the same places in different ways? Case studies focus on identity making in relation to the body and the course more broadly focuses on the intersection of race, class, gender, sexuality, and ethnicity as matrices of social and structural power relations and hierarchies.","cross_listed":["AFRST 224W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/wmgst-womens-and-gender-studies/200/wmgst-224","sections":[{"days":"TR","room":null,"types":["Writing Intensive Courses"],"status":"waitlisted","section":"01","building":null,"capacity":18,"comments":"Open to Srs., Jrs., Sophomores, & 1st Yrs","end_time":"11:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"11:45","start_date":"2027-01-20","start_time":"10:30"}],"start_time":"10:30:00","instructors":["Heather A. Merrill"]}]},
{"code":"WMGST 327","title":"Seminar on Aging","department":"Women's and Gender Studies","credits":1,"description":"Focuses on experiences of aging with attention to midlife and beyond. Examines images of aging in literature, film and media; ageism and its interconnections with race, class, sexual and gender identity; the relationships of aging to experiences of the body, health, economic issues, social and familial relationships; and death and dying. Considers how changing age distributions in the United States influence intergenerational relationships and social policy. Prerequisites, one course in women's studies or consent of instructor.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/wmgst-womens-and-gender-studies/300/wmgst-327","sections":[{"days":"TR","room":null,"types":["Cultural Diversity Course","Diversity Course"],"status":"open","section":"01","building":null,"capacity":12,"comments":null,"end_time":"15:45:00","meetings":[{"days":"TR","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"15:45","start_date":"2027-01-20","start_time":"14:30"}],"start_time":"14:30:00","instructors":["Margaret Gentry"]}]},
{"code":"WMGST 349","title":"Queer/Trans Cultural Produc","department":"Women's and Gender Studies","credits":1,"description":"This course explores queer and trans cultural production, ranging from zines, film, novels, photography, television, short fiction, painting, fanfiction, installation, poetry, performance art, music, video games, and more. On one level, it offers an interdisciplinary investigation of queer and trans representation, and both the possibilities and limitations of positive images and mainstream LGBTQ visibility. On another level, we explore the ways that writers, filmmakers, and artists find meaning through LGBTQ cultural production and artistic practices. We will also consider the politics of publication and distribution. The course takes up an intersectional approach, thinking about how LGBTQ cultural production is shaped by gender, race, ethnicity, nationality, class, and ability.","cross_listed":["CNMS 349"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/wmgst-womens-and-gender-studies/300/wmgst-349","sections":[{"days":"W","room":null,"types":[],"status":"open","section":"01","building":null,"capacity":12,"comments":null,"end_time":"16:00:00","meetings":[{"days":"W","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"16:00","start_date":"2027-01-20","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Amy Marvin"]}]},
{"code":"WMGST 405","title":"Sem Black Feminist Thought","department":"Women's and Gender Studies","credits":1,"description":"Interdisciplinary examination of the tradition of black feminist thought as it spans African and African-American heritages.Exploration of how black women are not simply victims of oppression but visionary agents of change.Areas examined include history, literature,music,art,education, sociology and film. There is intersectional analysis of the social, structural, and institutional hierarchies within the identities of women of African descent (gender/transgender, race, white supremacy, sexual/affectional orientation, class, color, and ability). Prerequisites, one course in women's studies or consent of instructor.","cross_listed":["AFRST 405"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/wmgst-womens-and-gender-studies/400/wmgst-405","sections":[{"days":"MW","room":null,"types":["Cultural Diversity Course","Diversity Course"],"status":"open","section":"01","building":null,"capacity":12,"comments":null,"end_time":"15:45:00","meetings":[{"days":"MW","room":null,"type":"LEC","building":null,"end_date":"2027-05-11","end_time":"15:45","start_date":"2027-01-20","start_time":"14:30"}],"start_time":"14:30:00","instructors":["Jessina Emmert"]}]},
{"code":"WMGST 550","title":"Senior Program","department":"Women's and Gender Studies","credits":1,"description":"A project or thesis on a topic in women's studies. Limited to senior concentrators and interdisciplinary concentrators with a focus on women's studies.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/wmgst-womens-and-gender-studies/500/wmgst-550","sections":[{"days":null,"room":null,"types":["Cultural Diversity Course","Senior Project"],"status":"open","section":"01","building":null,"capacity":40,"comments":"Open to Seniors Only.","end_time":null,"meetings":[],"start_time":null,"instructors":[]}]}
]$catalog$::jsonb as doc),
c as (
  select * from jsonb_to_recordset((select doc from catalog)) as x(
    code text, title text, department text, credits numeric, description text,
    cross_listed text[], catalog_url text, sections jsonb)
),
ins as (
  insert into public.courses (term_id, code, title, department, credits, description, cross_listed, catalog_url)
  select '2027SP', code, title, department, credits, description, coalesce(cross_listed, '{}'), catalog_url from c
  returning id, code
)
insert into public.sections (course_id, section, instructors, days, start_time, end_time, building, room, capacity, status, meetings, comments, types)
select ins.id, s.section, coalesce(s.instructors, '{}'), s.days, s.start_time, s.end_time, s.building, s.room,
       s.capacity, s.status, coalesce(s.meetings, '[]'), s.comments, coalesce(s.types, '{}')
from c
join ins using (code)
cross join lateral jsonb_to_recordset(c.sections) as s(
  section text, instructors text[], days text, start_time time, end_time time, building text, room text,
  capacity integer, status text, meetings jsonb, comments text, types text[]);
